window.AUTH=window.AUTH||{};window.AUTH["17-1712"]={"d":"17-1712","id":"2019/17-1712","n":"Thole v. U.S. Bank, N.A.","briefs":[{"k":"petitioner","label":"Brief of petitioners James J. Thole, et al.","date":"2019-09-11","url":"https://www.supremecourt.gov/DocketPDF/17/17-1712/115426/20190911140532908_Thole%20v.%20U.S.%20Bank%20---%20brief%20for%20the%20petitioners%20---%20FINAL.pdf","side":"pet","n":72},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-09-18","url":"https://www.supremecourt.gov/DocketPDF/17/17-1712/116284/20190918165138470_17-1712tsacUnited%20States.pdf","side":"us","n":67},{"k":"respondent","label":"Brief of respondents U.S. Bank, N.A., et al.","date":"2019-11-12","url":"https://www.supremecourt.gov/DocketPDF/17/17-1712/122119/20191112151612473_US%20Bank%20NA%20et%20al%20Response%20Brief%2020191112.pdf","side":"res","n":103},{"k":"reply","label":"Reply of petitioners James J. Thole, et al.","date":"2019-12-12","url":"https://www.supremecourt.gov/DocketPDF/17/17-1712/125349/20191212143604732_Thole%20v.%20U.S.%20Bank%20---%20petitioners%20reply%20brief%20---%20FINAL.pdf","side":"pet","n":28}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/590US2PP_web.pdf#page=126","tr":true,"items":[{"t":"case","label":"Aetna Health Inc. v. Davila","cite":"542 U.S. 200","y":2004,"id":"2003/02-1845","sc":1,"sum":"The Court held that Congress intended ERISA to provide a uniform system for regulating retirement schemes and benefits. If a state law conflicts with ERISA, therefore, ERISA must be used in its place.","sumSrc":"Oyez","by":{"0":"4, 43"}},{"t":"case","label":"Baker v. Carr","cite":"369 U.S. 186","y":1962,"id":"1960/6","sc":1,"sum":"The Court found that redistricting issues present justiciable questions, and in which the Court reframed its political question doctrine.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"0":"46","2":"59"}},{"t":"case","label":"Blair v. Comm’r of Internal Revenue","cite":"300 U.S. 5","y":1937,"id":"scdb/1936-134","sc":1,"op":2,"sum":"1. A judgment of the Circuit Court of Appealg holding a beneficiary named in a trust taxable upon trust income notwithstanding assignments previously made by him, and basing this conclusion upon the ground that, under the local law, the trust was a spendthrift trust giving the beneficiary no power to assign,-held inapplicable as res judicata in favor of the Government in proceedings to collect taxes from the same …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Cavender v. Cavender","cite":"114 U.S. 464","y":1885,"id":"scdb/1884-223","sc":1,"sum":"An answer in Chancery, setting forth material facts which should have been stated in the bill, but were omitted, is a waiver of the right to object to the bill for cause of the omission.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"2, 39"}},{"t":"case","label":"Cent. States, Se. & Sw. Areas Pension Fund v. Cent. Transport, Inc.","cite":"472 U.S. 559","y":1985,"id":"1984/82-2157","sc":1,"op":2,"sum":"Respondents must allow petitioners to conduct the requested audit.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 21","1":"9","2":"35"}},{"t":"case","label":"City of Los Angeles v. Lyons","cite":"461 U.S. 95","y":1983,"id":"1982/81-1064","sc":1,"sum":"In a 5-to-4 decision, the Court held that federal courts were without jurisdiction to entertain Lyons' claim for injunctive relief.","sumSrc":"Oyez","by":{"0":"50","2":"56, 57"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Clews v. Jamieson","cite":"182 U.S. 461","y":1901,"id":"scdb/1900-070","sc":1,"op":1,"sum":"As the governing committee of the stock exchange had no personal interest in the fund in question in this suit, which was placed in its possession in the trust and confidence that it would see that the purposes of the deposit were fulfilled, and that the moneys were paid out only in accordance with the terms of the trust under which it was deposited, there can be no question that the fund became thereby a, trust …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"236733.2 David v. Alphin","cite":"704 F.3d 327","y":2013,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/704/327/","op":1,"by":{"0":"45","2":"42, 45"}},{"t":"case","label":"Davis v. Davis Tr. Co.","cite":"145 S.E. 588","y":1928,"court":"W. Va.","url":"https://www.courtlistener.com/c/S.E./145/588/","by":{"0":"39"}},{"t":"case","label":"Erlich v. First Nat’l Bank of Princeton","cite":"505 A.2d 220","y":1984,"court":"N.J. Super.","url":"https://www.courtlistener.com/c/A.2d/505/220/","sum":"Noting “the soundness of the principle of diversification as the best protection against loss”.","sumSrc":"brief:0","by":{"0":"30, 43, 50"}},{"t":"case","label":"Glanton v. AdvancePCS, Inc.","cite":"465 F.3d 1123","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/465/1123/","by":{"0":"45"}},{"t":"case","label":"Harley v. Minn. Mining & Mfg. Co.","cite":"284 F.3d 901","y":2002,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/284/901/","ar":1,"by":{"0":"passim","1":"4, 11, 20","2":"14, 42"}},{"t":"case","label":"Harris Tr. & Sav. Bank v. Salomon Smith Barney, Inc.","cite":"530 U.S. 238","y":2000,"id":"1999/99-579","sc":1,"op":4,"sum":"The Court held that Section 502(a)(3)'s authorization to a plan \"participant, beneficiary, or fiduciary\" to bring a civil action for \"appropriate equitable relief\" extends to a suit against a nonfiduciary \"party in interest\" to a prohibited transaction barred by section 406(a). \"We reject,\" wrote Justice Thomas that, \"absent a substantive provision of ERISA expressly imposing a duty upon a nonfiduciary party in interest, the nonfiduciary party may not be held liable under [section 502(a)(3)].\" Justice Thomas concluded that \"[section 502(a)(3)] itself imposes certain duties, and therefore that liability under that provision does not depend on whether ERISA's substantive provisions impose a specific duty on the party being sued.\".","sumSrc":"Oyez","by":{"0":"20","1":"15, 27","2":"37","3":"8, 11"}},{"t":"case","label":"Horvath v. Keystone Health Plan E., Inc.","cite":"333 F.3d 450","y":2003,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/333/450/","by":{"0":"15, 45"}},{"t":"case","label":"Hughes Aircraft Co. v. Jacobson","cite":"525 U.S. 432","y":1999,"id":"1998/97-1287","sc":1,"op":4,"sum":"The Court held Hughes did not violate the ERISA by establishing an early retirement program and creating a noncontributory benefit structure for new participants. Justice Thomas, writing for the Court, said the plan amendments \"did not affect the rights of pre-existing plan participants and Hughes did not use the surplus for its own benefit.\".","sumSrc":"Oyez","by":{"0":"25, 26, 27","1":"3, 20, 21","2":"4, 34, 42, 43, 50, 55, 63","3":"6, 7"}},{"t":"case","label":"Jackson v. Smith","cite":"254 U.S. 586","y":1921,"id":"scdb/1920-206","sc":1,"sum":"Persons who knowingly join with a receiver in purchasing real estate at a sale made by the trustee of a deed of trust mortgage' securing a debt due the receivership, are jointly and severally liable to the receivership for all profits realized from the purchase.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"2, 34, 37","1":"17","2":"31"}},{"t":"case","label":"Johnson v. Superior Court in and for Maricopa Cty.","cite":"199 P.2d 827","y":1948,"court":"Ariz.","url":"https://www.courtlistener.com/c/P.2d/199/827/","by":{"0":"32","2":"32","3":"9"}},{"t":"case","label":"Kelsey v. Detroit Tr. Co.","cite":"251 N.W. 555","y":1933,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./251/555/","sum":"Explaining that at common law “a trustee could be removed and a new trustee substituted” when the trustee “dealt with the trust fund for his own personal profit and advancement,” “committed a breach of trust,” “neglected to use due care,” “or showed a lack of fidelity to the interests of the trust”.","sumSrc":"brief:0","by":{"0":"39"}},{"t":"case","label":"Kendall v. Emps. Ret. Plan of Avon Prods.","cite":"561 F.3d 112","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/561/112/","by":{"0":"46"}},{"t":"case","label":"236733.2 LaRue v. DeWolff, Boberg & Assocs.","cite":"552 U.S. 248","y":2008,"id":"2007/06-856","sc":1,"op":9,"ar":1,"by":{"0":"27","1":"10, 15, 18, 27","2":"2, 7, 8, 23, 35, 36, 39","3":"12"}},{"t":"case","label":"Lee v. Verizon Comm’ns Inc.","cite":"837 F.3d 523","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/837/523/","op":1,"ar":1,"by":{"0":"45","2":"21, 42, 45, 52"}},{"t":"case","label":"Lexmark Int’l, Inc. v. Static Control Components, Inc.","cite":"134 S. Ct. 1377","y":2014,"id":"2013/12-873","sc":1,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"0":"42, 47, 48","1":"24, 25, 26, 27","2":"59"}},{"t":"case","label":"Long Island Head Start Child Dev. Servs. v. Econ. Dev. Comm’n of Nassau Cty.","cite":"710 F.3d 57","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/710/57/","by":{"0":"45"}},{"t":"case","label":"Loren v. Blue Cross & Blue Shield of Mich.","cite":"505 F.3d 598","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/505/598/","by":{"0":"14, 15, 45, 46"}},{"t":"case","label":"Magruder v. Drury","cite":"235 U.S. 106","y":1914,"id":"scdb/1914-004","sc":1,"op":1,"ar":2,"sum":"On appeals from the Court of Appeals of the District of Columbia taken under the statutes in force before the adoption of the Judicial Code, this court reviews only the decree of that court, and objections in the lower courts not brought forward in the Court of Appeals cannot be considered here.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"2, 36, 37, 38","1":"17","3":"16"}},{"t":"case","label":"Mass. Mut. Life Ins. Co. v. Russell","cite":"473 U.S. 134","y":1985,"id":"1984/84-9","sc":1,"op":6,"sum":"Section 409(a) does not provide a cause of action for extracontractual damages to a beneficiary caused by improper or untimely processing of benefit claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"12, 25","2":"35, 36, 37, 38, 45, 50","3":"passim"}},{"t":"case","label":"Massachusetts v. EPA","cite":"549 U.S. 497","y":2007,"id":"2006/05-1120","sc":1,"op":1,"sum":"The Court ruled that states could sue the EPA for potential damage to their territory caused by global warming, and that the Clean Air Act imposes a duty upon the EPA to regulate the emissions of carbon dioxide and other gases that contribute to global warming.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"May v. May","cite":"167 U.S. 310","y":1897,"id":"scdb/1896-202","sc":1,"sum":"The power of a court of equity to remove a trustee, and to substitute another in his place, is incidental to its paramount duty to see that trusts are properly executed; and may properly be exercised, whenever such a state of mutual ill-feeling, growing out of his behavior, exists between him and his cotrustee or the beneficiaries, that his continuance in office would be detrimental to the execution of the trust, …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"McCullough v. AEGON USA Inc.","cite":"585 F.3d 1082","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/585/1082/","by":{"0":"passim","2":"14, 45"}},{"t":"case","label":"Mertens v. Hewitt Assocs.","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"sum":"ERISA does not authorize suits for money damages against nonfiduciaries who knowingly participate in a fiduciary's breach of fiduciary duty. ERISA §502(a)(3) permits plan participants to bring civil actions to obtain \"appropriate equitable relief\" to redress violations of the statute or a plan. Assuming, arguendo,that this creates a cause of action against nonfiduciaries who knowingly assist in a fiduciary's breach …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49","1":"12","2":"3, 34, 62"}},{"t":"case","label":"236733.2 Metro. Life Ins. Co. v. Glenn","cite":"554 U.S. 105","y":2008,"id":"2007/06-923","sc":1,"op":1,"sum":"The significance and severity of the conflict must be determined by the facts of each individual case. Here, the Court found that the evidence was sufficient to prove that a strong conflict of interest existed. Based on the principle of deference to lower court decisions, the Court affirmed the Sixth Circuit. Justice Stephen Breyer delivered the opinion of the Court.","sumSrc":"Oyez","by":{"0":"42","2":"36"}},{"t":"case","label":"Moore v. Bowes","cite":"64 P.2d 423","y":1937,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/64/423/","by":{"0":"40","2":"33","3":"18"}},{"t":"case","label":"Moskowitz v. Federman","cite":"51 N.E.2d 48","y":1948,"court":"Ohio Ct. App.","url":"https://www.courtlistener.com/c/N.E.2d/51/48/","by":{"0":"32"}},{"t":"case","label":"Mosser v. Darrow","cite":"341 U.S. 267","y":1951,"id":"scdb/1950-072","sc":1,"sum":"Respondent was properly surcharged as trustee in an amount representing the profits which these employees derived from their trading in securities of the debtors' subsidiaries.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37, 38"}},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"sum":"The Ninth Circuit’s judgments—that respondents, who are deportable for certain specified crimes, are not subject to 8 U. S. C. §1226(c)(2)’s mandatory-detention requirement because they were not arrested by immigration officials as soon as they were released from jail—are reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"47","2":"62","3":"21"}},{"t":"case","label":"Pegram v. Herdrich","cite":"530 U.S. 211","y":2000,"id":"1999/98-1949","sc":1,"op":3,"sum":"The Court held that mixed treatment and eligibility decisions to delay medical treatment by sending a patient to a HMO owned facility, with adverse consequences, made by a health maintenance organization through its physician, are not fiduciary decisions under ERISA.","sumSrc":"Oyez","by":{"0":"21","1":"12"}},{"t":"case","label":"Pilot Life Ins. Co. v. Dedeaux","cite":"481 U.S. 41","y":1987,"id":"1986/85-1043","sc":1,"sum":"ERISA pre-empts respondent's suit under state common law for alleged improper processing of his claim for benefits under the ERISAregulated benefit plan.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45, 48","1":"26"}},{"t":"case","label":"Riviera Cong. Assocs. v. Yassky","cite":"223 N.E.2d 876","y":1966,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/223/876/","by":{"0":"33","1":"11","2":"48"}},{"t":"case","label":"Scanlan v. Eisenberg","cite":"669 F.3d 838","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/669/838/","sum":"Finding Article III injury because “dereliction of their fiduciary duties is a direct invasion of Scanlan’s protected interest in the prudent and loyal administration of the trust”.","sumSrc":"brief:0","by":{"0":"passim","2":"25, 31, 32","3":"6, 7, 10"}},{"t":"case","label":"Senior v. Braden","cite":"295 U.S. 422","y":1935,"id":"scdb/1934-129","sc":1,"sum":"1. Where the validity of a state tax is challenged under the Federal Constitution, this Court must determine for itself the nature and incidence of the tax. P. 429..","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","2":"25"}},{"t":"case","label":"Soehnlen v. Fleet Owners Ins. Fund","cite":"844 F.3d 576","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/844/576/","by":{"0":"15"}},{"t":"case","label":"Spokeo v. Robins","cite":"136 S. Ct. 1540","y":2016,"id":"2015/13-1339","sc":1,"op":14,"ar":3,"sum":"The Court held that lower courts need to consider the elements of Article III standing analysis separately in determining whether standing is sufficient for a federal court to hear the case.","sumSrc":"Oyez","by":{"0":"passim","1":"9, 13, 15, 17, 18, 19","2":"34, 35, 38, 40, 41","3":"17, 21"}},{"t":"case","label":"236733.2 Sprint Comms. Co., L.P. v. APCC Servs.","cite":"554 U.S. 269","y":2008,"id":"2007/07-552","sc":1,"op":4,"sum":"Noting in the Article III standing context that “federal courts routinely entertain suits which will result in relief for parties that are not themselves directly bringing suit,” such as when “[t]rustees bring suits to beneft their trusts”.","sumSrc":"opinion","by":{"0":"passim","1":"15","2":"33, 49"}},{"t":"case","label":"Tibble v. Edison Int’l","cite":"135 S. Ct. 1823","y":2015,"id":"2014/13-550","sc":1,"ar":1,"sum":"The Court held that, according to trust law, the fiduciary duty includes a continuing duty to monitor investments, and that a breach of that duty within six years of the filing of a lawsuit under the Employee Retirement Income Security Act is sufficient to allow the case to proceed.","sumSrc":"Oyez","by":{"0":"5, 30"}},{"t":"case","label":"United States v. Carter","cite":"217 U.S. 286","y":1910,"id":"scdb/1909-135","sc":1,"sum":"Where both the courts below have concurred upon material facts, the burden rests bn the appellant to satisfy this court that such conclusions are erroneous.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"2, 37, 38","1":"17"}},{"t":"case","label":"United States v. Students Challenging Regulatory Agency Procedures (SCRAP)","cite":"412 U.S. 669","y":1973,"id":"1972/72-535","sc":1,"sum":"The Interstate Commerce Act permits railroads to file proposed freight rate increases, with at least 30 days' notice to the Interstate Commerce Commission (ICC) and the public before putting the new rates into effect. The ICC may, pursuant to § 15 (7) of the Act, suspend the operation of the proposed rates for as long as seven months, in order to investigate the lawfulness of the rates. At the end of the seven-month …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Varity Corp. v. Howe","cite":"516 U.S. 489","y":1996,"id":"1995/94-1471","sc":1,"op":8,"sum":"The Court held that, under the specific factual circumstances, Varity and Massey-Ferguson acted in their capacity as an ERISA fiduciary when they significantly and deliberately misled the plan's beneficiaries, thereby violating their fiduciary obligations imposed by ERISA.","sumSrc":"Oyez","by":{"0":"5, 42, 43","1":"3, 8, 10, 13, 27, 28","2":"7, 34, 36, 37, 60, 61, 63","3":"12"}},{"t":"case","label":"Vt. Agency of Nat. Res. v. U.S. ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"op":3,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"0":"8, 9","1":"14, 15","2":"22, 49, 50"}},{"t":"case","label":"Warger v. Shauers","cite":"135 S. Ct. 521","y":2014,"id":"2014/13-517","sc":1,"sum":"The Court held that the Federal Rule of Evidence 606(b) bars the testimony of a juror regarding statements made during deliberations for the purpose of showing alleged dishonesty by a prospective juror during jury selection.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Western R.R. Co. v. Nolan","cite":"48 N.Y. 513","y":1872,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.Y./48/513/","by":{"0":"34","1":"11"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"3"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","subs":["(a)","(b)"],"stext":{"head":"§1001. Congressional findings and declaration of policy","paras":[[0,"(a) Benefit plans as affecting interstate commerce and the Federal taxing power"],[0,"The Congress finds that the growth in size, scope, and numbers of employee benefit plans in recent years has been rapid and substantial; that the operational scope and economic impact of such plans is increasingly interstate; that the continued well-being and security of millions of employees and their dependents are directly affected by these plans; that they are affected with a national public interest; that they have become an important factor affecting the stability of employment and the successful development of industrial relations; that they have become an important factor in commerce because of the interstate character of their activities, and of the activities of their participants, and the employers, employee organizations, and other entities by which they are established or maintained; that a large volume of the activities of such plans are carried on by means of the mails and instrumentalities of interstate commerce; that owing to the lack of employee information and adequate safeguards concerning their operation, it is desirable in the interests of employees and their beneficiaries, and to provide for the general welfare and the free flow of commerce, that disclosure be made and safeguards be provided with respect to the establishment, operation, and administration of such plans; that they substantially affect the revenues of the United States because they are afforded preferential Federal tax treatment; that despite the enormous growth in such plans many employees with long years of employment are losing anticipated retirement benefits owing to the lack of vesting provisions in such plans; that owing to the inadequacy of current minimum standards, the soundness and stability of plans with respect to adequate funds to pay promised benefits may be endangered; that owing to the termination of plans before requisite funds have been accumulated, employees and their beneficiaries have been deprived of anticipated benefits; and that it is therefore desirable in the interests of employees and their beneficiaries, for the protection of the revenue of the United States, and to provide for the free flow of commerce, that minimum standards be provided assuring the equitable character of such plans and their financial soundness."],[0,"(b) Protection of interstate commerce and beneficiaries by requiring disclosure and reporting, setting standards of conduct, etc., for fiduciaries"],[0,"It is hereby declared to be the policy of this chapter to protect interstate commerce and the interests of participants in employee benefit plans and their beneficiaries, by requiring the disclosure and reporting to participants and beneficiaries of financial and other information with respect thereto, by establishing standards of conduct, responsibility, and obligation for fiduciaries of employee benefit plans, and by providing for appropriate remedies, sanctions, and ready access to the Federal courts."],[0,"(c) Protection of interstate commerce, the Federal taxing power, and beneficiaries by vesting of accrued benefits, setting minimum standards of funding, requiring termination insurance"],[0,"It is hereby further declared to be the policy of this chapter to protect interstate commerce, the Federal taxing power, and the interests of participants in private pension plans and their beneficiaries by improving the equitable character and the soundness of such plans by requiring them to vest the accrued benefits of employees with significant periods of service, to meet minimum standards of funding, and by requiring plan termination insurance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1001?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§1001. Congressional findings and declaration of policy","tname":"Labor","by":{"0":"38, 3, 38, 43, 48","1":"1, 2, 8, 15, 26","2":"59","3":"11"}},{"t":"usc","label":"29 U.S.C. § 1053","url":"https://www.law.cornell.edu/uscode/text/29/1053","subs":["(a)"],"stext":{"head":"§1053. Minimum vesting standards","paras":[[0,"(a) Nonforfeitability requirements"],[0,"Each pension plan shall provide that an employee's right to his normal retirement benefit is nonforfeitable upon the attainment of normal retirement age and in addition shall satisfy the requirements of paragraphs (1) and (2) of this subsection."],[1,"(1) A plan satisfies the requirements of this paragraph if an employee's rights in his accrued benefit derived from his own contributions are nonforfeitable."],[1,"(2)(A)(i) In the case of a defined benefit plan, a plan satisfies the requirements of this paragraph if it satisfies the requirements of clause (ii) or (iii)."],[1,"(ii) A plan satisfies the requirements of this clause if an employee who has completed at least 5 years of service has a nonforfeitable right to 100 percent of the employee's accrued benefit derived from employer contributions."],[1,"(iii) A plan satisfies the requirements of this clause if an employee has a nonforfeitable right to a percentage of the employee's accrued benefit derived from employer contributions determined under the following table:"],[1,"(B)(i) In the case of an individual account plan, a plan satisfies the requirements of this paragraph if it satisfies the requirements of clause (ii) or (iii)."],[1,"(ii) A plan satisfies the requirements of this clause if an employee who has completed at least 3 years of service has a nonforfeitable right to 100 percent of the employee's accrued benefit derived from employer contributions."],[1,"(iii) A plan satisfies the requirements of this clause if an employee has a nonforfeitable right to a percentage of the employee's accrued benefit derived from employer contributions determined under the following table:"],[1,"(3)(A) A right to an accrued benefit derived from employer contributions shall not be treated as forfeitable solely because the plan provides that it is not payable if the participant dies (except in the case of a survivor annuity which is payable as provided in section 1055 of this title)."],[1,"(B) A right to an accrued benefit derived from employer contributions shall not be treated as forfeitable solely because the plan provides that the payment of benefits is suspended for such period as the employee is employed, subsequent to the commencement of payment of such benefits—"],[2,"(i) in the case of a plan other than a multiemployer plan, by an employer who maintains the plan under which such benefits were being paid; and"],[2,"(ii) in the case of a multiemployer plan, in the same industry, in the same trade or craft, and the same geographic area covered by the plan, as when such benefits commenced."],[1,"The Secretary shall prescribe such regulations as may be necessary to carry out the purposes of this subparagraph, including regulations with respect to the meaning of the term \"employed\"."],[1,"(C) A right to an accrued benefit derived from employer contributions shall not be treated as forfeitable solely because plan amendments may be given retroactive application as provided in section 1082(d)(2) of this title."],[1,"(D)(i) A right to an accrued benefit derived from employer contributions shall not be treated as forfeitable solely because the plan provides that, in the case of a participant who does not have a nonforfeitable right to at least 50 percent of his accrued benefit derived from employer contributions, such accrued benefit may be forfeited on account of the withdrawal by the participant of any amount attributable to the benefit derived from mandatory contributions (as defined in the last sentence of section 1054(c)(2)(C) of this title) made by such participant."],[1,"(ii) Clause (i) shall not apply to a plan unless the plan provides that any accrued benefit forfeited under a plan provision described in such clause shall be restored upon repayment by the participant of the full amount of the withdrawal described in such clause plus, in the case of a defined benefit plan, interest. Such interest shall be computed on such amount at the rate determined for purposes of section 1054(c)(2)(C) of this title (if such subsection applies) on the date of such repayment (computed annually from the date of such withdrawal). The plan provision required under this clause may provide that such repayment must be made (I) in the case of a withdrawal on account of separation from service, before the earlier of 5 years after the first date on which the participant is subsequently re-employed by the employer, or the close of the first period of 5 consecutive 1-year breaks in service commencing after the withdrawal; or (II) in the case of any other withdrawal, 5 years after the date of the withdrawal."],[1,"(iii) In the case of accrued benefits derived from employer contributions which accrued before September 2, 1974, a right to such accrued benefit derived from employer contributions shall not be treated as forfeitable solely because the plan provides that an amount of such accrued benefit may be forfeited on account of the withdrawal by the participant of an amount attributable to the benefit derived from mandatory contributions, made by such participant before September 2, 1974, if such amount forfeited is proportional to such amount withdrawn. This clause shall not apply to any plan to which any mandatory contribution is made after September 2, 1974. The Secretary of the Treasury shall prescribe such regulations as may be necessary to carry out the purposes of this clause."],[1,"(iv) For purposes of this subparagraph, in the case of any class-year plan, a withdrawal of employee contributions shall be treated as a withdrawal of such contributions on a plan year by plan year basis in succeeding order of time."],[1,"(v) Cross reference.—"],[2,"For nonforfeitability where the employee has a nonforfeitable right to at least 50 percent of his accrued benefit, see section 1056(c) of this title."],[1,"(E)(i) A right to an accrued benefit derived from employer contributions under a multiemployer plan shall not be treated as forfeitable solely because the plan provides that benefits accrued as a result of service with the participant's employer before the employer had an obligation to contribute under the plan may not be payable if the employer ceases contributions to the multiemployer plan."],[1,"(ii) A participant's right to an accrued benefit derived from employer contributions under a multiemployer plan shall not be treated as forfeitable solely because—"],[2,"(I) the plan is amended to reduce benefits under section 1425 1 or 1441 of this title, or"],[2,"(II) benefit payments under the plan may be suspended under section 1426 or 1441 of this title."],[1,"(F) A matching contribution (within the meaning of section 401(m) of title 26) shall not be treated as forfeitable merely because such contribution is forfeitable if the contribution to which the matching contribution relates is treated as an excess contribution under section 401(k)(8)(B) of title 26, an excess deferral under section 402(g)(2)(A) of title 26, an erroneous automatic contribution under section 414(w) of title 26, or an excess aggregate contribution under section 401(m)(6)(B) of title 26."],[0,"(b) Computation of period of service"],[0,"(1) In computing the period of service under the plan for purposes of determining the nonforfeitable percentage under subsection (a)(2), all of an employee's years of service with the employer or employers maintaining the plan shall be taken into account, except that the following may be disregarded:"],[1,"(A) years of service before age 18,2"],[1,"(B) years of service during a period for which the employee declined to contribute to a plan requiring employee contributions,2"],[1,"(C) years of service with an employer during any period for which the employer did not maintain the plan or a predecessor plan, defined by the Secretary of the Treasury;"],[1,"(D) service not required to be taken into account under paragraph (3);"],[1,"(E) years of service before January 1, 1971, unless the employee has had at least 3 years of service after December 31, 1970;"],[1,"(F) years of service before this part first applies to the plan if such service would have been disregarded under the rules of the plan with regard to breaks in service, as in effect on the applicable date; and"],[1,"(G) in the case of a multiemployer plan, years of service—"],[2,"(i) with an employer after—"],[3,"(I) a complete withdrawal of such employer from the plan (within the meaning of section 1383 of this title), or"],[3,"(II) to the extent permitted by regulations prescribed by the Secretary of the Treasury, a partial withdrawal described in section 1385(b)(2)(A)(i) of this title in connection with the decertification of the collective bargaining representative; and"],[2,"(ii) with any employer under the plan after the termination date of the plan under section 1348 of this title."],[0,"(2)(A) For purposes of this section, except as provided in subparagraph (C), the term \"year of service\" means a calendar year, plan year, or other 12-consecutive month period designated by the plan (and not prohibited under regulations prescribed by the Secretary) during which the participant has completed 1,000 hours of service."],[0,"(B) For purposes of this section, the term \"hour of service\" has the meaning provided by section 1052(a)(3)(C) of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1053?type=usc&year=mostrecent&link-type=html"},"head":"§1053. Minimum vesting standards","tname":"Labor","by":{"0":"25","2":"4"}},{"t":"usc","label":"29 U.S.C. § 1083","url":"https://www.law.cornell.edu/uscode/text/29/1083","subs":["(a)","(d)","(g)","(h)","(i)"],"stext":{"head":"§1083. Minimum funding standards for single-employer defined benefit pension plans","paras":[[0,"(a) Minimum required contribution"],[0,"For purposes of this section and section 1082(a)(2)(A) of this title, except as provided in subsection (f), the term \"minimum required contribution\" means, with respect to any plan year of a single-employer plan—"],[1,"(1) in any case in which the value of plan assets of the plan (as reduced under subsection (f)(4)(B)) is less than the funding target of the plan for the plan year, the sum of—"],[2,"(A) the target normal cost of the plan for the plan year,"],[2,"(B) the shortfall amortization charge (if any) for the plan for the plan year determined under subsection (c), and"],[2,"(C) the waiver amortization charge (if any) for the plan for the plan year as determined under subsection (e); or"],[1,"(2) in any case in which the value of plan assets of the plan (as reduced under subsection (f)(4)(B)) equals or exceeds the funding target of the plan for the plan year, the target normal cost of the plan for the plan year reduced (but not below zero) by such excess."],[0,"(b) Target normal cost"],[0,"For purposes of this section:"],[0,"(1) In general"],[1,"Except as provided in subsection (i)(2) with respect to plans in at-risk status, the term \"target normal cost\" means, for any plan year, the excess of—"],[2,"(A) the sum of—"],[3,"(i) the present value of all benefits which are expected to accrue or to be earned under the plan during the plan year, plus"],[3,"(ii) the amount of plan-related expenses expected to be paid from plan assets during the plan year, over"],[2,"(B) the amount of mandatory employee contributions expected to be made during the plan year."],[0,"(2) Special rule for increase in compensation"],[1,"For purposes of this subsection, if any benefit attributable to services performed in a preceding plan year is increased by reason of any increase in compensation during the current plan year, the increase in such benefit shall be treated as having accrued during the current plan year."],[0,"(c) Shortfall amortization charge"],[0,"(1) In general"],[1,"For purposes of this section, the shortfall amortization charge for a plan for any plan year is the aggregate total (not less than zero) of the shortfall amortization installments for such plan year with respect to any shortfall amortization base which has not been fully amortized under this subsection."],[0,"(2) Shortfall amortization installment"],[1,"For purposes of paragraph (1)—"],[0,"(A) Determination"],[2,"The shortfall amortization installments are the amounts necessary to amortize the shortfall amortization base of the plan for any plan year in level annual installments over the 7-plan-year period beginning with such plan year."],[0,"(B) Shortfall installment"],[2,"The shortfall amortization installment for any plan year in the 7-plan-year period under subparagraph (A) with respect to any shortfall amortization base is the annual installment determined under subparagraph (A) for that year for that base."],[0,"(C) Segment rates"],[2,"In determining any shortfall amortization installment under this paragraph, the plan sponsor shall use the segment rates determined under subparagraph (C) of subsection (h)(2), applied under rules similar to the rules of subparagraph (B) of subsection (h)(2)."],[0,"(D) Special election for eligible plan years"],[0,"(i) In general"],[3,"If a plan sponsor elects to apply this subparagraph with respect to the shortfall amortization base of a plan for any eligible plan year (in this subparagraph and paragraph (7) referred to as an \"election year\"), then, notwithstanding subparagraphs (A) and (B)—"],[4,"(I) the shortfall amortization installments with respect to such base shall be determined under clause (ii) or (iii), whichever is specified in the election, and"],[4,"(II) the shortfall amortization installment for any plan year in the 9-plan-year period described in clause (ii) or the 15-plan-year period described in clause (iii), respectively, with respect to such shortfall amortization base is the annual installment determined under the applicable clause for that year for that base."],[0,"(ii) 2 plus 7 amortization schedule"],[3,"The shortfall amortization installments determined under this clause are—"],[4,"(I) in the case of the first 2 plan years in the 9-plan-year period beginning with the election year, interest on the shortfall amortization base of the plan for the election year (determined using the effective interest rate for the plan for the election year), and"],[4,"(II) in the case of the last 7 plan years in such 9-plan-year period, the amounts necessary to amortize the remaining balance of the shortfall amortization base of the plan for the election year in level annual installments over such last 7 plan years (using the segment rates under subparagraph (C) for the election year)."],[0,"(iii) 15-year amortization"],[3,"The shortfall amortization installments determined under this subparagraph are the amounts necessary to amortize the shortfall amortization base of the plan for the election year in level annual installments over the 15-plan-year period beginning with the election year (using the segment rates under subparagraph (C) for the election year)."],[0,"(iv) Election"],[0,"(I) In general"],[4,"The plan sponsor of a plan may elect to have this subparagraph apply to not more than 2 eligible plan years with respect to the plan, except that in the case of a plan described in section 106 of the Pension Protection Act of 2006, the plan sponsor may only elect to have this subparagraph apply to a plan year beginning in 2011."],[0,"(II) Amortization schedule"],[4,"Such election shall specify whether the amortization schedule under clause (ii) or (iii) shall apply to an election year, except that if a plan sponsor elects to have this subparagraph apply to 2 eligible plan years, the plan sponsor must elect the same schedule for both years."],[0,"(III) Other rules"],[4,"Such election shall be made at such time, and in such form and manner, as shall be prescribed by the Secretary of the Treasury, and may be revoked only with the consent of the Secretary of the Treasury. The Secretary of the Treasury shall, before granting a revocation request, provide the Pension Benefit Guaranty Corporation an opportunity to comment on the conditions applicable to the treatment of any portion of the election year shortfall amortization base that remains unamortized as of the revocation date."],[0,"(v) Eligible plan year"],[3,"For purposes of this subparagraph, the term \"eligible plan year\" means any plan year beginning in 2008, 2009, 2010, or 2011, except that a plan year shall only be treated as an eligible plan year if the due date under subsection (j)(1) for the payment of the minimum required contribution for such plan year occurs on or after June 25, 2010."],[0,"(vi) Reporting"],[3,"A plan sponsor of a plan who makes an election under clause (i) shall—"],[4,"(I) give notice of the election to participants and beneficiaries of the plan, and"],[4,"(II) inform the Pension Benefit Guaranty Corporation of such election in such form and manner as the Director of the Pension Benefit Guaranty Corporation may prescribe."],[0,"(vii) Increases in required installments in certain cases"],[3,"For increases in required contributions in cases of excess compensation or extraordinary dividends or stock redemptions, see paragraph (7)."],[0,"(3) Shortfall amortization base"],[1,"For purposes of this section, the shortfall amortization base of a plan for a plan year is—"],[2,"(A) the funding shortfall of such plan for such plan year, minus"],[2,"(B) the present value (determined using the segment rates determined under subparagraph (C) of subsection (h)(2), applied under rules similar to the rules of subparagraph (B) of subsection (h)(2)) of the aggregate total of the shortfall amortization installments and waiver amortization installments which have been determined for such plan year and any succeeding plan year with respect to the shortfall amortization bases and waiver amortization bases of the plan for any plan year preceding such plan year."],[0,"(4) Funding shortfall"],[1,"For purposes of this section, the funding shortfall of a plan for any plan year is the excess (if any) of—"],[2,"(A) the funding target of the plan for the plan year, over"],[2,"(B) the value of plan assets of the plan (as reduced under subsection (f)(4)(B)) for the plan year which are held by the plan on the valuation date."],[0,"(5) Exemption from new shortfall amortization base"],[2,"In any case in which the value of plan assets of the plan (as reduced under subsection (f)(4)(A)) is equal to or greater than the funding target of the plan for the plan year, the shortfall amortization base of the plan for such plan year shall be zero."],[0,"(6) Early deemed amortization upon attainment of funding target"],[1,"In any case in which the funding shortfall of a plan for a plan year is zero, for purposes of determining the shortfall amortization charge for such plan year and succeeding plan years, the shortfall amortization bases for all preceding plan years (and all shortfall amortization installments determined with respect to such bases) shall be reduced to zero."],[0,"(7) Increases in alternate required installments in cases of excess compensation or extraordinary dividends or stock redemptions"],[0,"(A) In general"],[2,"If there is an installment acceleration amount with respect to a plan for any plan year in the restriction period with respect to an election year under paragraph (2)(D), then the shortfall amortization installment otherwise determined and payable under such paragraph for such plan year shall, subject to the limitation under subparagraph (B), be increased by such amount."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1083?type=usc&year=mostrecent&link-type=html"},"head":"§1083. Minimum funding standards for single-employer defined benefit pension plans","tname":"Labor","by":{"0":"12, 13","1":"4","2":"5, 5, 5, 5, 5"}},{"t":"usc","label":"29 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/29/1103","subs":["(a)","(c)(1)","(c)"],"stext":{"head":"§1103. Establishment of trust","paras":[[0,"(a) Benefit plan assets to be held in trust; authority of trustees"],[0,"Except as provided in subsection (b), all assets of an employee benefit plan shall be held in trust by one or more trustees. Such trustee or trustees shall be either named in the trust instrument or in the plan instrument described in section 1102(a) of this title or appointed by a person who is a named fiduciary, and upon acceptance of being named or appointed, the trustee or trustees shall have exclusive authority and discretion to manage and control the assets of the plan, except to the extent that—"],[1,"(1) the plan expressly provides that the trustee or trustees are subject to the direction of a named fiduciary who is not a trustee, in which case the trustees shall be subject to proper directions of such fiduciary which are made in accordance with the terms of the plan and which are not contrary to this chapter, or"],[1,"(2) authority to manage, acquire, or dispose of assets of the plan is delegated to one or more investment managers pursuant to section 1102(c)(3) of this title."],[0,"(b) Exceptions"],[0,"The requirements of subsection (a) of this section shall not apply—"],[1,"(1) to any assets of a plan which consist of insurance contracts or policies issued by an insurance company qualified to do business in a State;"],[1,"(2) to any assets of such an insurance company or any assets of a plan which are held by such an insurance company;"],[1,"(3) to a plan—"],[2,"(A) some or all of the participants of which are employees described in section 401(c)(1) of title 26; or"],[2,"(B) which consists of one or more individual retirement accounts described in section 408 of title 26;"],[1,"to the extent that such plan's assets are held in one or more custodial accounts which qualify under section 401(f) or 408(h) of title 26, whichever is applicable."],[1,"(4) to a plan which the Secretary exempts from the requirement of subsection (a) and which is not subject to any of the following provisions of this chapter—"],[2,"(A) part 2 of this subtitle,"],[2,"(B) part 3 of this subtitle, or"],[2,"(C) subchapter III of this chapter; or"],[1,"(5) to a contract established and maintained under section 403(b) of title 26 to the extent that the assets of the contract are held in one or more custodial accounts pursuant to section 403(b)(7) of title 26."],[1,"(6) Any plan, fund or program under which an employer, all of whose stock is directly or indirectly owned by employees, former employees or their beneficiaries, proposes through an unfunded arrangement to compensate retired employees for benefits which were forfeited by such employees under a pension plan maintained by a former employer prior to the date such pension plan became subject to this chapter."],[0,"(c) Assets of plan not to inure to benefit of employer; allowable purposes of holding plan assets"],[0,"(1) Except as provided in paragraph (2), (3), or (4) 1 or subsection (d), or under sections 1342 and 1344 of this title (relating to termination of insured plans), or under section 420 of title 26 (as in effect on December 29, 2022), the assets of a plan shall never inure to the benefit of any employer and shall be held for the exclusive purposes of providing benefits to participants in the plan and their beneficiaries and defraying reasonable expenses of administering the plan."],[0,"(2)(A) In the case of a contribution, or a payment of withdrawal liability under part 1 of subtitle E of subchapter III—"],[1,"(i) if such contribution or payment is made by an employer to a plan (other than a multiemployer plan) by a mistake of fact, paragraph (1) shall not prohibit the return of such contribution to the employer within one year after the payment of the contribution, and"],[1,"(ii) if such contribution or payment is made by an employer to a multiemployer plan by a mistake of fact or law (other than a mistake relating to whether the plan is described in section 401(a) of title 26 or the trust which is part of such plan is exempt from taxation under section 501(a) of title 26), paragraph (1) shall not prohibit the return of such contribution or payment to the employer within 6 months after the plan administrator determines that the contribution was made by such a mistake."],[0,"(B) If a contribution is conditioned on initial qualification of the plan under section 401 or 403(a) of title 26, and if the plan receives an adverse determination with respect to its initial qualification, then paragraph (1) shall not prohibit the return of such contribution to the employer within one year after such determination, but only if the application for the determination is made by the time prescribed by law for filing the employer's return for the taxable year in which such plan was adopted, or such later date as the Secretary of the Treasury may prescribe."],[0,"(C) If a contribution is conditioned upon the deductibility of the contribution under section 404 of title 26, then, to the extent the deduction is disallowed, paragraph (1) shall not prohibit the return to the employer of such contribution (to the extent disallowed) within one year after the disallowance of the deduction."],[0,"(3) In the case of a withdrawal liability payment which has been determined to be an overpayment, paragraph (1) shall not prohibit the return of such payment to the employer within 6 months after the date of such determination."],[0,"(d) Termination of plan"],[0,"(1) Upon termination of a pension plan to which section 1321 of this title does not apply at the time of termination and to which this part applies (other than a plan to which no employer contributions have been made) the assets of the plan shall be allocated in accordance with the provisions of section 1344 of this title, except as otherwise provided in regulations of the Secretary."],[0,"(2) The assets of a welfare plan which terminates shall be distributed in accordance with the terms of the plan, except as otherwise provided in regulations of the Secretary."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1103?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1103. Establishment of trust","tname":"Labor","by":{"0":"27, 4, 23, 4, 23, 25, 27","1":"21","2":"5, 44, 45, 44, 45","3":"1, 5, 7"}},{"t":"usc","label":"29 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/29/1104","subs":["(a)(1)","(a)","(a)(1)(D)"],"stext":{"head":"§1104. Fiduciary duties","paras":[[0,"(a) Prudent man standard of care"],[0,"(1) Subject to sections 1103(c) and (d), 1342, and 1344 of this title, a fiduciary shall discharge his duties with respect to a plan solely in the interest of the participants and beneficiaries and—"],[1,"(A) for the exclusive purpose of:"],[2,"(i) providing benefits to participants and their beneficiaries; and"],[2,"(ii) defraying reasonable expenses of administering the plan;"],[1,"(B) with the care, skill, prudence, and diligence under the circumstances then prevailing that a prudent man acting in a like capacity and familiar with such matters would use in the conduct of an enterprise of a like character and with like aims;"],[1,"(C) by diversifying the investments of the plan so as to minimize the risk of large losses, unless under the circumstances it is clearly prudent not to do so; and"],[1,"(D) in accordance with the documents and instruments governing the plan insofar as such documents and instruments are consistent with the provisions of this subchapter and subchapter III."],[0,"(2) In the case of an eligible individual account plan (as defined in section 1107(d)(3) of this title), the diversification requirement of paragraph (1)(C) and the prudence requirement (only to the extent that it requires diversification) of paragraph (1)(B) is not violated by acquisition or holding of qualifying employer real property or qualifying employer securities (as defined in section 1107(d)(4) and (5) of this title)."],[0,"(b) Indicia of ownership of assets outside jurisdiction of district courts"],[0,"Except as authorized by the Secretary by regulations, no fiduciary may maintain the indicia of ownership of any assets of a plan outside the jurisdiction of the district courts of the United States."],[0,"(c) Control over assets by participant or beneficiary"],[0,"(1)(A) In the case of a pension plan which provides for individual accounts and permits a participant or beneficiary to exercise control over the assets in his account, if a participant or beneficiary exercises control over the assets in his account (as determined under regulations of the Secretary)—"],[1,"(i) such participant or beneficiary shall not be deemed to be a fiduciary by reason of such exercise, and"],[1,"(ii) no person who is otherwise a fiduciary shall be liable under this part for any loss, or by reason of any breach, which results from such participant's or beneficiary's exercise of control, except that this clause shall not apply in connection with such participant or beneficiary for any blackout period during which the ability of such participant or beneficiary to direct the investment of the assets in his or her account is suspended by a plan sponsor or fiduciary."],[0,"(B) If a person referred to in subparagraph (A)(ii) meets the requirements of this subchapter in connection with authorizing and implementing the blackout period, any person who is otherwise a fiduciary shall not be liable under this subchapter for any loss occurring during such period."],[0,"(C) For purposes of this paragraph, the term \"blackout period\" has the meaning given such term by section 1021(i)(7) of this title."],[0,"(2) In the case of a simple retirement account established pursuant to a qualified salary reduction arrangement under section 408(p) of title 26, a participant or beneficiary shall, for purposes of paragraph (1), be treated as exercising control over the assets in the account upon the earliest of—"],[1,"(A) an affirmative election among investment options with respect to the initial investment of any contribution,"],[1,"(B) a rollover to any other simple retirement account or individual retirement plan, or"],[1,"(C) one year after the simple retirement account is established."],[0,"No reports, other than those required under section 1021(g) of this title, shall be required with respect to a simple retirement account established pursuant to such a qualified salary reduction arrangement."],[0,"(3) In the case of a pension plan which makes a transfer to an individual retirement account or annuity of a designated trustee or issuer under section 401(a)(31)(B) of title 26, the participant or beneficiary shall, for purposes of paragraph (1), be treated as exercising control over the assets in the account or annuity upon—"],[1,"(A) the earlier of—"],[2,"(i) a rollover of all or a portion of the amount to another individual retirement account or annuity; or"],[2,"(ii) one year after the transfer is made; or"],[1,"(B) a transfer that is made in a manner consistent with guidance provided by the Secretary."],[0,"(4)(A) In any case in which a qualified change in investment options occurs in connection with an individual account plan, a participant or beneficiary shall not be treated for purposes of paragraph (1) as not exercising control over the assets in his account in connection with such change if the requirements of subparagraph (C) are met in connection with such change."],[0,"(B) For purposes of subparagraph (A), the term \"qualified change in investment options\" means, in connection with an individual account plan, a change in the investment options offered to the participant or beneficiary under the terms of the plan, under which—"],[1,"(i) the account of the participant or beneficiary is reallocated among one or more remaining or new investment options which are offered in lieu of one or more investment options offered immediately prior to the effective date of the change, and"],[1,"(ii) the stated characteristics of the remaining or new investment options provided under clause (i), including characteristics relating to risk and rate of return, are, as of immediately after the change, reasonably similar to those of the existing investment options as of immediately before the change."],[0,"(C) The requirements of this subparagraph are met in connection with a qualified change in investment options if—"],[1,"(i) at least 30 days and no more than 60 days prior to the effective date of the change, the plan administrator furnishes written notice of the change to the participants and beneficiaries, including information comparing the existing and new investment options and an explanation that, in the absence of affirmative investment instructions from the participant or beneficiary to the contrary, the account of the participant or beneficiary will be invested in the manner described in subparagraph (B),"],[1,"(ii) the participant or beneficiary has not provided to the plan administrator, in advance of the effective date of the change, affirmative investment instructions contrary to the change, and"],[1,"(iii) the investments under the plan of the participant or beneficiary as in effect immediately prior to the effective date of the change were the product of the exercise by such participant or beneficiary of control over the assets of the account within the meaning of paragraph (1)."],[0,"(5) Default investment arrangements.—"],[1,"(A) In general.—For purposes of paragraph (1), a participant or beneficiary in an individual account plan meeting the notice requirements of subparagraph (B) shall be treated as exercising control over the assets in the account with respect to the amount of contributions and earnings which, in the absence of an investment election by the participant or beneficiary, are invested by the plan in accordance with regulations prescribed by the Secretary. The regulations under this subparagraph shall provide guidance on the appropriateness of designating default investments that include a mix of asset classes consistent with capital preservation or long-term capital appreciation, or a blend of both."],[1,"(B) Notice requirements.—"],[2,"(i) In general.—The requirements of this subparagraph are met if each participant or beneficiary—"],[3,"(I) receives, within a reasonable period of time before each plan year, a notice explaining the employee's right under the plan to designate how contributions and earnings will be invested and explaining how, in the absence of any investment election by the participant or beneficiary, such contributions and earnings will be invested, and"],[3,"(II) has a reasonable period of time after receipt of such notice and before the beginning of the plan year to make such designation."],[2,"(ii) Form of notice.—The requirements of clauses (i) and (ii) of section 401(k)(12)(D) of title 26 shall apply with respect to the notices described in this subparagraph."],[0,"(6) Default investment arrangements for a pension-linked emergency savings account.—For purposes of paragraph (1), a participant in a pension-linked emergency savings account shall be treated as exercising control over the assets in the account with respect to the amount of contributions and earnings which are invested in accordance with section 1193(c)(1)(A)(iii) of this title."],[0,"(d) Plan terminations"],[0,"(1) If, in connection with the termination of a pension plan which is a single-employer plan, there is an election to establish or maintain a qualified replacement plan, or to increase benefits, as provided under section 4980(d) of title 26, a fiduciary shall discharge the fiduciary's duties under this subchapter and subchapter III in accordance with the following requirements:"],[1,"(A) In the case of a fiduciary of the terminated plan, any requirement—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1104?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1104. Fiduciary duties","tname":"Labor","by":{"0":"4, 43, passim","1":"2, 15, 19","2":"5, 6, 35","3":"1, 11"}},{"t":"usc","label":"29 U.S.C. § 1106","url":"https://www.law.cornell.edu/uscode/text/29/1106","subs":["(a)(1)","(b)(3)"],"stext":{"head":"§1106. Prohibited transactions","paras":[[0,"(a) Transactions between plan and party in interest"],[0,"Except as provided in section 1108 of this title:"],[1,"(1) A fiduciary with respect to a plan shall not cause the plan to engage in a transaction, if he knows or should know that such transaction constitutes a direct or indirect—"],[2,"(A) sale or exchange, or leasing, of any property between the plan and a party in interest;"],[2,"(B) lending of money or other extension of credit between the plan and a party in interest;"],[2,"(C) furnishing of goods, services, or facilities between the plan and a party in interest;"],[2,"(D) transfer to, or use by or for the benefit of a party in interest, of any assets of the plan; or"],[2,"(E) acquisition, on behalf of the plan, of any employer security or employer real property in violation of section 1107(a) of this title."],[1,"(2) No fiduciary who has authority or discretion to control or manage the assets of a plan shall permit the plan to hold any employer security or employer real property if he knows or should know that holding such security or real property violates section 1107(a) of this title."],[0,"(b) Transactions between plan and fiduciary"],[0,"A fiduciary with respect to a plan shall not—"],[1,"(1) deal with the assets of the plan in his own interest or for his own account,"],[1,"(2) in his individual or in any other capacity act in any transaction involving the plan on behalf of a party (or represent a party) whose interests are adverse to the interests of the plan or the interests of its participants or beneficiaries, or"],[1,"(3) receive any consideration for his own personal account from any party dealing with such plan in connection with a transaction involving the assets of the plan."],[0,"(c) Transfer of real or personal property to plan by party in interest"],[0,"A transfer of real or personal property by a party in interest to a plan shall be treated as a sale or exchange if the property is subject to a mortgage or similar lien which the plan assumes or if it is subject to a mortgage or similar lien which a party-in-interest placed on the property within the 10-year period ending on the date of the transfer."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1106?type=usc&year=mostrecent&link-type=html"},"head":"§1106. Prohibited transactions","tname":"Labor","by":{"0":"4, 43, 4, 4","1":"2","2":"6, 35"}},{"t":"usc","label":"29 U.S.C. § 1109","url":"https://www.law.cornell.edu/uscode/text/29/1109","subs":["(a)"],"stext":{"head":"§1109. Liability for breach of fiduciary duty","paras":[[0,"(a) Any person who is a fiduciary with respect to a plan who breaches any of the responsibilities, obligations, or duties imposed upon fiduciaries by this subchapter shall be personally liable to make good to such plan any losses to the plan resulting from each such breach, and to restore to such plan any profits of such fiduciary which have been made through use of assets of the plan by the fiduciary, and shall be subject to such other equitable or remedial relief as the court may deem appropriate, including removal of such fiduciary. A fiduciary may also be removed for a violation of section 1111 of this title."],[0,"(b) No fiduciary shall be liable with respect to a breach of fiduciary duty under this subchapter if such breach was committed before he became a fiduciary or after he ceased to be a fiduciary."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1109?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1109. Liability for breach of fiduciary duty","tname":"Labor","by":{"0":"passim, 5, 30, 34, 50","1":"2, 7, 18, 25, 2, 6, 12, 14, 25","2":"35, 36, 6","3":"12, 20"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","subs":["(a)","(a)(1)","(a)(2)","(a)(3)","(a)(1)(B)","(a)(4)","(a)(5)","(d)(1)","(h)"],"stext":{"head":"§1132. Civil enforcement","paras":[[0,"(a) Persons empowered to bring a civil action"],[0,"A civil action may be brought—"],[1,"(1) by a participant or beneficiary—"],[2,"(A) for the relief provided for in subsection (c) of this section, or"],[2,"(B) to recover benefits due to him under the terms of his plan, to enforce his rights under the terms of the plan, or to clarify his rights to future benefits under the terms of the plan;"],[1,"(2) by the Secretary, or by a participant, beneficiary or fiduciary for appropriate relief under section 1109 of this title;"],[1,"(3) by a participant, beneficiary, or fiduciary (A) to enjoin any act or practice which violates any provision of this subchapter or the terms of the plan, or (B) to obtain other appropriate equitable relief (i) to redress such violations or (ii) to enforce any provisions of this subchapter or the terms of the plan;"],[1,"(4) by the Secretary, or by a participant, or beneficiary for appropriate relief in the case of a violation of section 1025(c) or 1032(a) of this title;"],[1,"(5) except as otherwise provided in subsection (b), by the Secretary (A) to enjoin any act or practice which violates any provision of this subchapter, or (B) to obtain other appropriate equitable relief (i) to redress such violation or (ii) to enforce any provision of this subchapter;"],[1,"(6) by the Secretary to collect any civil penalty under paragraph (2), (4), (5), (6), (7), (8), or (9) of subsection (c) or under subsection (i) or (l);"],[1,"(7) by a State to enforce compliance with a qualified medical child support order (as defined in section 1169(a)(2)(A) of this title);"],[1,"(8) by the Secretary, or by an employer or other person referred to in section 1021(f)(1) of this title, (A) to enjoin any act or practice which violates subsection (f) of section 1021 of this title, or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection;"],[1,"(9) in the event that the purchase of an insurance contract or insurance annuity in connection with termination of an individual's status as a participant covered under a pension plan with respect to all or any portion of the participant's pension benefit under such plan constitutes a violation of part 4 of this title 1 or the terms of the plan, by the Secretary, by any individual who was a participant or beneficiary at the time of the alleged violation, or by a fiduciary, to obtain appropriate relief, including the posting of security if necessary, to assure receipt by the participant or beneficiary of the amounts provided or to be provided by such insurance contract or annuity, plus reasonable prejudgment interest on such amounts;"],[1,"(10) in the case of a multiemployer plan that has been certified by the actuary to be in endangered or critical status under section 1085 of this title, if the plan sponsor—"],[2,"(A) has not adopted a funding improvement or rehabilitation plan under that section by the deadline established in such section, or"],[2,"(B) fails to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section,"],[1,"by an employer that has an obligation to contribute with respect to the multiemployer plan or an employee organization that represents active participants in the multiemployer plan, for an order compelling the plan sponsor to adopt a funding improvement or rehabilitation plan or to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section and the funding improvement or rehabilitation plan; or"],[1,"(11) in the case of a multiemployer plan, by an employee representative, or any employer that has an obligation to contribute to the plan, (A) to enjoin any act or practice which violates subsection (k) of section 1021 of this title (or, in the case of an employer, subsection (l) of such section), or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection."],[0,"(b) Plans qualified under Internal Revenue Code; maintenance of actions involving delinquent contributions"],[0,"(1) In the case of a plan which is qualified under section 401(a), 403(a), or 405(a) 2 of title 26 (or with respect to which an application to so qualify has been filed and has not been finally determined) the Secretary may exercise his authority under subsection (a)(5) with respect to a violation of, or the enforcement of, parts 2 and 3 of this subtitle (relating to participation, vesting, and funding), only if—"],[1,"(A) requested by the Secretary of the Treasury, or"],[1,"(B) one or more participants, beneficiaries, or fiduciaries, of such plan request in writing (in such manner as the Secretary shall prescribe by regulation) that he exercise such authority on their behalf. In the case of such a request under this paragraph he may exercise such authority only if he determines that such violation affects, or such enforcement is necessary to protect, claims of participants or beneficiaries to benefits under the plan."],[0,"(2) The Secretary shall not initiate an action to enforce section 1145 of this title."],[0,"(3) Except as provided in subsections (c)(9) and (a)(6) (with respect to collecting civil penalties under subsection (c)(9)), the Secretary is not authorized to enforce under this part any requirement of part 7 against a health insurance issuer offering health insurance coverage in connection with a group health plan (as defined in section 1191b(a)(1) of this title). Nothing in this paragraph shall affect the authority of the Secretary to issue regulations to carry out such part."],[0,"(c) Administrator's refusal to supply requested information; penalty for failure to provide annual report in complete form"],[0,"(1) Any administrator (A) who fails to meet the requirements of paragraph (1) or (4) of section 1166 2 of this title, section 1021(e)(1) of this title, section 1021(f) of this title,,3 section 1025(a) of this title, or section 1032(a) of this title with respect to a participant or beneficiary, or (B) who fails or refuses to comply with a request for any information which such administrator is required by this subchapter to furnish to a participant or beneficiary (unless such failure or refusal results from matters reasonably beyond the control of the administrator) by mailing the material requested to the last known address of the requesting participant or beneficiary within 30 days after such request may in the court's discretion be personally liable to such participant or beneficiary in the amount of up to $100 a day from the date of such failure or refusal, and the court may in its discretion order such other relief as it deems proper. For purposes of this paragraph, each violation described in subparagraph (A) with respect to any single participant, and each violation described in subparagraph (B) with respect to any single participant or beneficiary, shall be treated as a separate violation."],[0,"(2) The Secretary may assess a civil penalty against any plan administrator of up to $1,000 a day from the date of such plan administrator's failure or refusal to file the annual report required to be filed with the Secretary under section 1021(b)(1) of this title. For purposes of this paragraph, an annual report that has been rejected under section 1024(a)(4) of this title for failure to provide material information shall not be treated as having been filed with the Secretary."],[0,"(3) Any employer maintaining a plan who fails to meet the notice requirement of section 1021(d) of this title with respect to any participant or beneficiary or who fails to meet the requirements of section 1021(e)(2) of this title with respect to any person or who fails to meet the requirements of section 1082(d)(12)(E) 2 of this title with respect to any person may in the court's discretion be liable to such participant or beneficiary or to such person in the amount of up to $100 a day from the date of such failure, and the court may in its discretion order such other relief as it deems proper."],[0,"(4) The Secretary may assess a civil penalty of not more than $1,000 a day for each violation by any person of subsection (j), (k), or (l) of section 1021 of this title or section 1144(e)(3) of this title."],[0,"(5) The Secretary may assess a civil penalty against any person of up to $1,000 a day from the date of the person's failure or refusal to file the information required to be filed by such person with the Secretary under regulations prescribed pursuant to section 1021(g) of this title."],[0,"(6) If, within 30 days of a request by the Secretary to a plan administrator for documents under section 1024(a)(6) of this title, the plan administrator fails to furnish the material requested to the Secretary, the Secretary may assess a civil penalty against the plan administrator of up to $100 a day from the date of such failure (but in no event in excess of $1,000 per request). No penalty shall be imposed under this paragraph for any failure resulting from matters reasonably beyond the control of the plan administrator."],[0,"(7) The Secretary may assess a civil penalty against a plan administrator of up to $100 a day from the date of the plan administrator's failure or refusal to provide notice to participants and beneficiaries in accordance with subsection (i) or (m) of section 1021 of this title. For purposes of this paragraph, each violation with respect to any single participant or beneficiary shall be treated as a separate violation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1132?type=usc&year=mostrecent&link-type=html"},"op":11,"head":"§1132. Civil enforcement","tname":"Labor","by":{"0":"14, 42, 49, 33, passim, passim","1":"8, 11, 17, 1, 7, 19, passim, passim","2":"6, 39, 39, 41, 45, 55, 58, 59, 60, 62, 41, 50, 58, 59, 60, 61, 62, 6, 39, 36, 45, 7, 39","3":"1, 14, 17, 20, 20"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"0":"passim","1":"passim"}},{"t":"case","label":"Burrows v. Palmer","cite":"125 N.E.2d 484","y":1955,"court":"Ill.","url":"https://www.courtlistener.com/c/N.E.2d/125/484/","by":{"1":"21"}},{"t":"case","label":"Clapper v. Amnesty Int’l USA","cite":"568 U.S. 398","y":2013,"id":"2012/11-1025","sc":1,"op":1,"ar":3,"sum":"The Court held that the respondents lacked Article III standing against FISA because fear of intercepted communication and costs incurred to avoid intercepted communications are not injuries.","sumSrc":"Oyez","by":{"1":"22","2":"19, 53, 54"}},{"t":"case","label":"(III) Cases—Continued: Commissioner v. Keystone Consol. Indus., Inc.","cite":"508 U.S. 152","y":1993,"id":"1992/91-1677","sc":1,"op":1,"sum":"When applied to an employer's funding obligation, the contribution of unencumbered property to a defined benefit plan is a prohibited \"sale or exchange\" under §4975(c)(1)(A).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2"}},{"t":"case","label":"Daily Income Fund, Inc. v. Fox","cite":"464 U.S. 523","y":1984,"id":"1983/82-1200","sc":1,"sum":"Rule 23.1 does not apply to an action brought by an investment company shareholder under § 36(b), and thus the plaintiff in such a case need not first make a demand upon the company's directors before bringing suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14","2":"46"}},{"t":"case","label":"Davoue v. Fanning","cite":"2 Johns. Ch. 252","y":1816,"court":"N.Y. Ch.","url":"https://www.courtlistener.com/c/Johns.%20Ch./2/252/","by":{"1":"17"}},{"t":"case","label":"Fifth Third Bancorp v. Dudenhoeffer","cite":"573 U.S. 409","y":2014,"id":"2013/12-751","sc":1,"op":1,"ar":4,"sum":"The Court held that a trustee of an employee stock ownership plan is subject to the same duty of prudence as the trustee of a Employee Retirement Income Security Act.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Firestone Tire & Rubber Co. v. Bruch","cite":"489 U.S. 101","y":1989,"id":"1988/87-1054","sc":1,"sum":"Petitioner Firestone Tire & Rubber Co. (Firestone) maintained, and was the plan administrator and fiduciary of, a termination pay plan and two other unfunded employee benefit plans governed by the Employee Retirement Income Security Act of 1974 (ERISA), 29 U. S. C. § 1001 et seq. After Firestone sold its Plastics Division to Occidental Petroleum Co. (Occidental), respondents, Plastics Division employees who were …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"9","3":"2"}},{"t":"case","label":"Gollust v. Mendell","cite":"501 U.S. 115","y":1991,"id":"1990/90-659","sc":1,"op":3,"ar":1,"sum":"Mendell has satisfied the statute's standing requirements.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14","2":"41, 47, 60","3":"20"}},{"t":"case","label":"Havens Realty Corp. v. Coleman","cite":"455 U.S. 363","y":1982,"id":"1981/80-988","sc":1,"op":1,"sum":"Section 804 of the Fair Housing Act of 1968 (Act) makes unlawful various forms of discriminatory housing practices. Section 812(a) authorizes civil actions to enforce §804 and requires that suit be brought within 180 days after the alleged occurrence of a discriminatory practice. A class action for declaratory, injunctive, and monetary relief was brought in Federal District Court against petitioners-Havens Realty …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18","2":"39, 40"}},{"t":"case","label":"Hobby Lobby Stores, Inc. v. Sebelius","cite":"723 F.3d 1114","y":2013,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/723/1114/","op":1,"by":{"1":"14"}},{"t":"case","label":"Lockheed Corp. v. Spink","cite":"517 U.S. 882","y":1996,"id":"1995/95-809","sc":1,"op":2,"sum":"In unanimous and 7-2 decisions, announced by Justice Clarence Thomas, the Court ruled that businesses may condition early retirement benefits on the forfeiture of the right to sue in a job-related claim. The Court also ruled that the government could not retroactively apply retirement income benefit laws.","sumSrc":"Oyez","by":{"1":"3"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"op":1,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"1":"23","2":"19, 30, 40, 53"}},{"t":"case","label":"Merchants’ Cotton Press & Storage Co. v. Insurance Co. of N. Am.","cite":"151 U.S. 368","y":1894,"id":"scdb/1893-294","sc":1,"sum":"A railroad company agreed with a cotton compress company that the latter should receive and compress all the cotton which the railroad might have to transport in compressed condition, and that it should insure the same for the benefit of the railroad company, or of the owners of the cotton, for a certain compensation which the railroad company agreed to pay weelily. It was further agreed that the compress company, …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"13","2":"47"}},{"t":"case","label":"Nachman Corp. v. Pension Benefit Guar. Corp.","cite":"446 U.S. 359","y":1980,"id":"1979/78-1557","sc":1,"sum":"The plan's limitation of liability clause does not prevent the vested benefits from being characterized as \"nonforfeitable\" and thus covered by the insurance program. Petitioner's argument that the Title I definition of \"nonforfeitable\" determines which benefits are insured under Title IV, that thus benefits are not insured unless they are \"unconditional\" and \"legally enforceable against the plan,\" that because of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Shaw v. Weisz","cite":"91 N.E.2d 81","y":1950,"court":"Ill. App.","url":"https://www.courtlistener.com/c/N.E.2d/91/81/","by":{"1":"21"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"op":2,"sum":"Explaining this Court's independent duty to assure itself of Article III standing.","sumSrc":"opinion","by":{"1":"8","2":"19, 59"}},{"t":"case","label":"US Airways, Inc. v. McCutchen","cite":"569 U.S. 88","y":2013,"id":"2012/11-1285","sc":1,"sum":"The Court held that when a contract is silent on allocation of relief, the parties' intentions are best determined by the common-fund doctrine.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","subs":["(7)","(8)","(13)","(34)","(35)"],"stext":{"head":"§1002. Definitions","paras":[[0,"For purposes of this subchapter:"],[0,"(1) The terms \"employee welfare benefit plan\" and \"welfare plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that such plan, fund, or program was established or is maintained for the purpose of providing for its participants or their beneficiaries, through the purchase of insurance or otherwise, (A) medical, surgical, or hospital care or benefits, or benefits in the event of sickness, accident, disability, death or unemployment, or vacation benefits, apprenticeship or other training programs, or day care centers, scholarship funds, or prepaid legal services, or (B) any benefit described in section 186(c) of this title (other than pensions on retirement or death, and insurance to provide such pensions)."],[0,"(2)(A) Except as provided in subparagraph (B), the terms \"employee pension benefit plan\" and \"pension plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that by its express terms or as a result of surrounding circumstances such plan, fund, or program—"],[1,"(i) provides retirement income to employees, or"],[1,"(ii) results in a deferral of income by employees for periods extending to the termination of covered employment or beyond,"],[0,"regardless of the method of calculating the contributions made to the plan, the method of calculating the benefits under the plan or the method of distributing benefits from the plan. A distribution from a plan, fund, or program shall not be treated as made in a form other than retirement income or as a distribution prior to termination of covered employment solely because such distribution is made to an employee who has attained age 62 and who is not separated from employment at the time of such distribution."],[0,"(B) The Secretary may by regulation prescribe rules consistent with the standards and purposes of this chapter providing one or more exempt categories under which—"],[1,"(i) severance pay arrangements, and"],[1,"(ii) supplemental retirement income payments, under which the pension benefits of retirees or their beneficiaries are supplemented to take into account some portion or all of the increases in the cost of living (as determined by the Secretary of Labor) since retirement,"],[0,"shall, for purposes of this subchapter, be treated as welfare plans rather than pension plans. In the case of any arrangement or payment a principal effect of which is the evasion of the standards or purposes of this chapter applicable to pension plans, such arrangement or payment shall be treated as a pension plan. An applicable voluntary early retirement incentive plan (as defined in section 457(e)(11)(D)(ii) of title 26) making payments or supplements described in section 457(e)(11)(D)(i) of title 26, and an applicable employment retention plan (as defined in section 457(f)(4)(C) of title 26) making payments of benefits described in section 457(f)(4)(A) of title 26, shall, for purposes of this subchapter, be treated as a welfare plan (and not a pension plan) with respect to such payments and supplements."],[0,"(C) A pooled employer plan shall be treated as—"],[1,"(i) a single employee pension benefit plan or single pension plan; and"],[1,"(ii) a plan to which section 1060(a) of this title applies."],[0,"(3) The term \"employee benefit plan\" or \"plan\" means an employee welfare benefit plan or an employee pension benefit plan or a plan which is both an employee welfare benefit plan and an employee pension benefit plan."],[0,"(4) The term \"employee organization\" means any labor union or any organization of any kind, or any agency or employee representation committee, association, group, or plan, in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning an employee benefit plan, or other matters incidental to employment relationships; or any employees' beneficiary association organized for the purpose in whole or in part, of establishing such a plan."],[0,"(5) The term \"employer\" means any person acting directly as an employer, or indirectly in the interest of an employer, in relation to an employee benefit plan; and includes a group or association of employers acting for an employer in such capacity."],[0,"(6) The term \"employee\" means any individual employed by an employer."],[0,"(7) The term \"participant\" means any employee or former employee of an employer, or any member or former member of an employee organization, who is or may become eligible to receive a benefit of any type from an employee benefit plan which covers employees of such employer or members of such organization, or whose beneficiaries may be eligible to receive any such benefit."],[0,"(8) The term \"beneficiary\" means a person designated by a participant, or by the terms of an employee benefit plan, who is or may become entitled to a benefit thereunder."],[0,"(9) The term \"person\" means an individual, partnership, joint venture, corporation, mutual company, joint-stock company, trust, estate, unincorporated organization, association, or employee organization."],[0,"(10) The term \"State\" includes any State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, and the Canal Zone. The term \"United States\" when used in the geographic sense means the States and the Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act (43 U.S.C. 1331–1343)."],[0,"(11) The term \"commerce\" means trade, traffic, commerce, transportation, or communication between any State and any place outside thereof."],[0,"(12) The term \"industry or activity affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce, and includes any activity or industry \"affecting commerce\" within the meaning of the Labor Management Relations Act, 1947 [29 U.S.C. 141 et seq.], or the Railway Labor Act [45 U.S.C. 151 et seq.]."],[0,"(13) The term \"Secretary\" means the Secretary of Labor."],[0,"(14) The term \"party in interest\" means, as to an employee benefit plan—"],[1,"(A) any fiduciary (including, but not limited to, any administrator, officer, trustee, or custodian), counsel, or employee of such employee benefit plan;"],[1,"(B) a person providing services to such plan;"],[1,"(C) an employer any of whose employees are covered by such plan;"],[1,"(D) an employee organization any of whose members are covered by such plan;"],[1,"(E) an owner, direct or indirect, of 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of a corporation.1"],[2,"(ii) the capital interest or the profits interest of a partnership, or"],[2,"(iii) the beneficial interest of a trust or unincorporated enterprise,"],[1,"which is an employer or an employee organization described in subparagraph (C) or (D);"],[1,"(F) a relative (as defined in paragraph (15)) of any individual described in subparagraph (A), (B), (C), or (E);"],[1,"(G) a corporation, partnership, or trust or estate of which (or in which) 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of such corporation,"],[2,"(ii) the capital interest or profits interest of such partnership, or"],[2,"(iii) the beneficial interest of such trust or estate,"],[1,"is owned directly or indirectly, or held by persons described in subparagraph (A), (B), (C), (D), or (E);"],[1,"(H) an employee, officer, director (or an individual having powers or responsibilities similar to those of officers or directors), or a 10 percent or more shareholder directly or indirectly, of a person described in subparagraph (B), (C), (D), (E), or (G), or of the employee benefit plan; or"],[1,"(I) a 10 percent or more (directly or indirectly in capital or profits) partner or joint venturer of a person described in subparagraph (B), (C), (D), (E), or (G)."],[0,"The Secretary, after consultation and coordination with the Secretary of the Treasury, may by regulation prescribe a percentage lower than 50 percent for subparagraph (E) and (G) and lower than 10 percent for subparagraph (H) or (I). The Secretary may prescribe regulations for determining the ownership (direct or indirect) of profits and beneficial interests, and the manner in which indirect stockholdings are taken into account. Any person who is a party in interest with respect to a plan to which a trust described in section 501(c)(22) of title 26 is permitted to make payments under section 1403 of this title shall be treated as a party in interest with respect to such trust."],[0,"(15) The term \"relative\" means a spouse, ancestor, lineal descendant, or spouse of a lineal descendant."],[0,"(16)(A) The term \"administrator\" means—"],[1,"(i) the person specifically so designated by the terms of the instrument under which the plan is operated;"],[1,"(ii) if an administrator is not so designated, the plan sponsor; or"],[1,"(iii) in the case of a plan for which an administrator is not designated and a plan sponsor cannot be identified, such other person as the Secretary may by regulation prescribe."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1002?type=usc&year=mostrecent&link-type=html"},"head":"§1002. Definitions","tname":"Labor","by":{"1":"10, 10, 1","2":"4, 4"}},{"t":"usc","label":"29 U.S.C. § 1081-1085a","url":"https://www.law.cornell.edu/uscode/text/29/1081-1085a","by":{"1":"22"}},{"t":"usc","label":"29 U.S.C. § 1081","url":"https://www.law.cornell.edu/uscode/text/29/1081","subs":["(a)"],"by":{"1":"3"}},{"t":"usc","label":"29 U.S.C. § 1082","url":"https://www.law.cornell.edu/uscode/text/29/1082","by":{"1":"3"}},{"t":"usc","label":"29 U.S.C. § 1105","url":"https://www.law.cornell.edu/uscode/text/29/1105","by":{"1":"12"}},{"t":"usc","label":"29 U.S.C. § 1344","url":"https://www.law.cornell.edu/uscode/text/29/1344","subs":["(d)","(d)(1)"],"by":{"1":"21, 20"}},{"t":"usc","label":"42 U.S.C. § 3601","url":"https://www.law.cornell.edu/uscode/text/42/3601","by":{"1":"18"}},{"t":"usc","label":"26 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/26/401","subs":["(a)(2)"],"stext":{"head":"§401. Qualified pension, profit-sharing, and stock bonus plans","paras":[[0,"(a) Requirements for qualification"],[0,"A trust created or organized in the United States and forming part of a stock bonus, pension, or profit-sharing plan of an employer for the exclusive benefit of his employees or their beneficiaries shall constitute a qualified trust under this section—"],[1,"(1) if contributions are made to the trust by such employer, or employees, or both, or by another employer who is entitled to deduct his contributions under section 404(a)(3)(B) (relating to deduction for contributions to profit-sharing and stock bonus plans), or by a charitable remainder trust pursuant to a qualified gratuitous transfer (as defined in section 664(g)(1)), for the purpose of distributing to such employees or their beneficiaries the corpus and income of the fund accumulated by the trust in accordance with such plan;"],[1,"(2) if under the trust instrument it is impossible, at any time prior to the satisfaction of all liabilities with respect to employees and their beneficiaries under the trust, for any part of the corpus or income to be (within the taxable year or thereafter) used for, or diverted to, purposes other than for the exclusive benefit of his employees or their beneficiaries (but this paragraph shall not be construed, in the case of a multiemployer plan, to prohibit the return of a contribution within 6 months after the plan administrator determines that the contribution was made by a mistake of fact or law (other than a mistake relating to whether the plan is described in section 401(a) or the trust which is part of such plan is exempt from taxation under section 501(a), or the return of any withdrawal liability payment determined to be an overpayment within 6 months of such determination));"],[1,"(3) if the plan of which such trust is a part satisfies the requirements of section 410 (relating to minimum participation standards); and"],[1,"(4) if the contributions or benefits provided under the plan do not discriminate in favor of highly compensated employees (within the meaning of section 414(q)). For purposes of this paragraph, there shall be excluded from consideration employees described in section 410(b)(3)(A) and (C)."],[1,"(5) Special rules relating to nondiscrimination requirements.—"],[2,"(A) Salaried or clerical employees.—A classification shall not be considered discriminatory within the meaning of paragraph (4) or section 410(b)(2)(A)(i) merely because it is limited to salaried or clerical employees."],[2,"(B) Contributions and benefits may bear uniform relationship to compensation.—A plan shall not be considered discriminatory within the meaning of paragraph (4) merely because the contributions or benefits of, or on behalf of, the employees under the plan bear a uniform relationship to the compensation (within the meaning of section 414(s)) of such employees."],[2,"(C) Certain disparity permitted.—A plan shall not be considered discriminatory within the meaning of paragraph (4) merely because the contributions or benefits of, or on behalf of, the employees under the plan favor highly compensated employees (as defined in section 414(q)) in the manner permitted under subsection (l)."],[2,"(D) Integrated defined benefit plan.—"],[3,"(i) In general.—A defined benefit plan shall not be considered discriminatory within the meaning of paragraph (4) merely because the plan provides that the employer-derived accrued retirement benefit for any participant under the plan may not exceed the excess (if any) of—"],[4,"(I) the participant's final pay with the employer, over"],[4,"(II) the employer-derived retirement benefit created under Federal law attributable to service by the participant with the employer."],[0,"For purposes of this clause, the employer-derived retirement benefit created under Federal law shall be treated as accruing ratably over 35 years."],[3,"(ii) Final pay.—For purposes of this subparagraph, the participant's final pay is the compensation (as defined in section 414(q)(4)) paid to the participant by the employer for any year—"],[4,"(I) which ends during the 5-year period ending with the year in which the participant separated from service for the employer, and"],[4,"(II) for which the participant's total compensation from the employer was highest."],[2,"(E) 2 or more plans treated as single plan.—For purposes of determining whether 2 or more plans of an employer satisfy the requirements of paragraph (4) when considered as a single plan—"],[3,"(i) Contributions.—If the amount of contributions on behalf of the employees allowed as a deduction under section 404 for the taxable year with respect to such plans, taken together, bears a uniform relationship to the compensation (within the meaning of section 414(s)) of such employees, the plans shall not be considered discriminatory merely because the rights of employees to, or derived from, the employer contributions under the separate plans do not become nonforfeitable at the same rate."],[3,"(ii) Benefits.—If the employees' rights to benefits under the separate plans do not become nonforfeitable at the same rate, but the levels of benefits provided by the separate plans satisfy the requirements of regulations prescribed by the Secretary to take account of the differences in such rates, the plans shall not be considered discriminatory merely because of the difference in such rates."],[2,"(F) Social security retirement age.—For purposes of testing for discrimination under paragraph (4)—"],[3,"(i) the social security retirement age (as defined in section 415(b)(8)) shall be treated as a uniform retirement age, and"],[3,"(ii) subsidized early retirement benefits and joint and survivor annuities shall not be treated as being unavailable to employees on the same terms merely because such benefits or annuities are based in whole or in part on an employee's social security retirement age (as so defined)."],[2,"(G) Governmental plans.—Paragraphs (3) and (4) shall not apply to a governmental plan (within the meaning of section 414(d))."],[1,"(6) A plan shall be considered as meeting the requirements of paragraph (3) during the whole of any taxable year of the plan if on one day in each quarter it satisfied such requirements."],[1,"(7) A trust shall not constitute a qualified trust under this section unless the plan of which such trust is a part satisfies the requirements of section 411 (relating to minimum vesting standards)."],[1,"(8) A trust forming part of a defined benefit plan shall not constitute a qualified trust under this section unless the plan provides that forfeitures must not be applied to increase the benefits any employee would otherwise receive under the plan."],[1,"(9) Required distributions.—"],[2,"(A) In general.—A trust shall not constitute a qualified trust under this subsection unless the plan provides that the entire interest of each employee—"],[3,"(i) will be distributed to such employee not later than the required beginning date, or"],[3,"(ii) will be distributed, beginning not later than the required beginning date, in accordance with regulations, over the life of such employee or over the lives of such employee and a designated beneficiary (or over a period not extending beyond the life expectancy of such employee or the life expectancy of such employee and a designated beneficiary)."],[2,"(B) Required distribution where employee dies before entire interest is distributed.—"],[3,"(i) Where distributions have begun under subparagraph (A)(ii).—A trust shall not constitute a qualified trust under this section unless the plan provides that if—"],[4,"(I) the distribution of the employee's interest has begun in accordance with subparagraph (A)(ii), and"],[4,"(II) the employee dies before his entire interest has been distributed to him,"],[0,"the remaining portion of such interest will be distributed at least as rapidly as under the method of distributions being used under subparagraph (A)(ii) as of the date of his death."],[3,"(ii) 5-year rule for other cases.—A trust shall not constitute a qualified trust under this section unless the plan provides that, if an employee dies before the distribution of the employee's interest has begun in accordance with subparagraph (A)(ii), the entire interest of the employee will be distributed within 5 years after the death of such employee."],[3,"(iii) Exception to 5-year rule for certain amounts payable over life of beneficiary.—If—"],[4,"(I) any portion of the employee's interest is payable to (or for the benefit of) a designated beneficiary,"],[4,"(II) such portion will be distributed (in accordance with regulations) over the life of such designated beneficiary (or over a period not extending beyond the life expectancy of such beneficiary), and"],[4,"(III) such distributions begin not later than 1 year after the date of the employee's death or such later date as the Secretary may by regulations prescribe,"],[0,"for purposes of clause (ii), the portion referred to in subclause (I) shall be treated as distributed on the date on which such distributions begin."],[3,"(iv) Special rule for surviving spouse of employee.—If the designated beneficiary referred to in clause (iii)(I) is the surviving spouse of the employee and the surviving spouse elects the treatment in this clause—"],[4,"(I) the regulations referred to in clause (iii)(II) shall treat the surviving spouse as if the surviving spouse were the employee,"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/401?type=usc&year=mostrecent&link-type=html"},"head":"§401. Qualified pension, profit-sharing, and stock bonus plans","tname":"Internal Revenue Code","by":{"1":"21","3":"1, 5, 7"}},{"t":"usc","label":"26 U.S.C. § 412","url":"https://www.law.cornell.edu/uscode/text/26/412","by":{"1":"3"}},{"t":"usc","label":"26 U.S.C. § 4980","url":"https://www.law.cornell.edu/uscode/text/26/4980","subs":["(d)(1)","(d)(2)","(d)(3)"],"by":{"1":"21, 21, 21"}},{"t":"case","label":"Adedipe v. U.S. Bank, N.A.","cite":"62 F. Supp. 3d 879","y":2014,"court":"D. Minn.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/62/879/","by":{"2":"11, 12, 30, 34, 52, 56"}},{"t":"case","label":"Already, LLC v. Nike, Inc.","cite":"568 U.S. 85","y":2013,"id":"2012/11-982","sc":1,"sum":"The Court held that a covenant not to sue invalidates a company’s counterclaim for trademark enforcement.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Americold Realty Trust v. Conagra Foods, Inc.","cite":"136 S. Ct. 1012","y":2016,"id":"2015/14-1382","sc":1,"sum":"The Court determined that, for the purposes of diversity jurisdiction, the citizenship of a trust is based on the citizenship of its members, which includes the beneficiary shareholders as well as the trustees.","sumSrc":"Oyez","by":{"2":"36"}},{"t":"case","label":"Beck v. PACE Int’l Union","cite":"551 U.S. 96","y":2007,"id":"2006/05-1448","sc":1,"op":2,"sum":"The Court held that \"merger is not a permissible method of terminating a single-employer defined-benefit pension plan.\" Therefore, PACE's argument that Crown was required by ERISA to consider merger as a method of terminating the pension plan was rejected.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Carey v. Piphus","cite":"435 U.S. 247","y":1978,"id":"1977/76-1149","sc":1,"sum":"The Court held that the purpose of the Civil Rights Act of 1871 is to compensate people for injuries caused by the deprivation of civil rights, which means that compensation cannot occur without proof of injury. However, the definition of injury must be adapted to fit the civil rights in question.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Chandris, Inc. v. Latsis","cite":"515 U.S. 347","y":1995,"id":"1994/94-325","sc":1,"sum":"Respondent Latsis' duties as a superintendent engineer for petitioner Chandris, Inc., required him to take voyages on Chandris' ships. He lost substantial vision in one eye after a condition that he developed while on one of those voyages went untreated by a ship's doctor. Following his recuperation, he sailed to Germany on the S. S. Galileo and stayed with the ship while it was in drydock for refurbishment. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"51"}},{"t":"case","label":"CIGNA Corp. v. Amara","cite":"563 U.S. 421","y":2011,"id":"2010/09-804","sc":1,"sum":"The Court held that the U.S. District Court for the District of Connecticut did not have the authority to reform CIGNA's pension plan.","sumSrc":"Oyez","by":{"2":"61"}},{"t":"case","label":"Cohen v. United States Tr. Sec. Corp.","cite":"40 N.E.2d 282","y":1942,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.2d/40/282/","by":{"2":"24"}},{"t":"case","label":"Dodge v. Woolsey","cite":"59 U.S. 331","y":1855,"id":"scdb/1855-055","sc":1,"sum":"A stockholder in a corporation has a remedy in chancery against the directors, to pro-' vent them from doing acts which would amount to a violation of the charter, or to prevent any misapplication of then capital or profits which might lessen the value of the shares, if the acts intended to be done amount to what is called in law a breach of trust or duty.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"47"}},{"t":"case","label":"Duncan v. Muzyn","cite":"885 F.3d 422","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/885/422/","by":{"2":"42"}},{"t":"case","label":"Exxon Co., USA v. Sofec, Inc.","cite":"517 U.S. 830","y":1996,"id":"1995/95-129","sc":1,"op":2,"sum":"The Court held that a plaintiff in admiralty that is the superseding cause of its own injury, and thus the sole, proximate cause, cannot recover part of its damages from tort-feasors or contracting partners whose blameworthy actions were causes in fact of the injury.","sumSrc":"Oyez","by":{"2":"51"}},{"t":"case","label":"FEC v. National Conservative Political Action Committee","cite":"470 U.S. 480","y":1985,"id":"1984/83-1032","sc":1,"sum":"The Court held that the expenditures prohibited by the Federal Election Campaign Act were \"at the core of the First Amendment\" and could not be restricted by the government. The Court rejected the notion that the PACs' form of organization diminished their entitlement to First Amendment protection.","sumSrc":"Oyez","by":{"2":"60, 61","3":"20"}},{"t":"case","label":"Glanton v. AdvancePCS Inc.","cite":"465 F.3d 1125","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/465/1125/","by":{"2":"42, 45"}},{"t":"case","label":"Haines v. Elliot","cite":"58 A. 718","y":1904,"court":"Conn.","url":"https://www.courtlistener.com/c/A./58/718/","by":{"2":"58","3":"19"}},{"t":"case","label":"Harrison v. Randall","cite":"68 Eng. Rep. 562","y":1852,"url":"https://www.courtlistener.com/c/Eng.%20Rep./68/562/","by":{"2":"24","3":"13"}},{"t":"case","label":"Hawes v. Oakland","cite":"104 U.S. 450","y":1881,"id":"scdb/1881-077","sc":1,"by":{"2":"49"}},{"t":"case","label":"Hollingsworth v. Perry","cite":"570 U.S. 693","y":2013,"id":"2012/12-144","sc":1,"op":3,"ar":1,"sum":"The Court found that the proponents of California's same-sex marriage ban (Proposition 8) do not have standing to appeal the decision that made Proposition 8 unconstitutional.","sumSrc":"Oyez","by":{"2":"18, 20, 46, 47"}},{"t":"case","label":"Jacobson v. Hughes Aircraft Co.","cite":"105 F.3d 1288","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/105/1288/","by":{"2":"43"}},{"t":"case","label":"Kamen v. Kemper Fin. Servs.","cite":"500 U.S. 90","y":1991,"id":"1990/90-516","sc":1,"sum":"A court entertaining a derivative action under the ICA must apply the demand futility exception as it is defined by the law of the State of incorporation.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"51"}},{"t":"case","label":"Lewis v. Casey","cite":"518 U.S. 343","y":1996,"id":"1995/94-1511","sc":1,"sum":"The Court held that the success of Casey's systemic challenge was dependent on the ability to show widespread actual injury, and the District Court's failure to identify anything more than isolated instances of actual injury rendered its finding of a systemic Bounds violation invalid.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"McChord v. Caldwell’s Ex’r","cite":"29 S.W. 440","y":1895,"court":"Ky.","url":"https://www.courtlistener.com/c/S.W./29/440/","by":{"2":"32","3":"9"}},{"t":"case","label":"Michoud v. Girod","cite":"45 U.S. 503","y":1846,"id":"scdb/1846-039","sc":1,"op":1,"sum":"A person cannot legally purchase on his own account that which his duty or trust requires him to sell on account of another, nor purchase on account of another that which he sells on his own account. He is not allowed to unite the two opposite characters of buyer and seller.-","sumSrc":"Headnote (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"Ortiz v. Fibreboard Corp.","cite":"527 U.S. 815","y":1999,"id":"1998/97-1704","sc":1,"sum":"The Court held that \"applicants for contested certification [of a mandatory settlement class on a limited fund theory under Rule 23(b)(1)(B)] must show that the fund is limited by more than the agreement of the parties, and has been allocated to claimants belonging within the class by a process addressing any conflicting interests of class members.\" \"The record on which the District Court rested its certification of the class for the purpose of the global settlement did not support the essential premises of mandatory limited fund actions.","sumSrc":"Oyez","by":{"2":"59"}},{"t":"case","label":"Perelman v. Perelman","cite":"793 F.3d 368","y":2015,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/793/368/","by":{"2":"42, 45"}},{"t":"case","label":"Piatt v. Longworth’s Devisees","cite":"27 Ohio St. 159","y":1875,"url":"https://www.courtlistener.com/c/Ohio%20St./27/159/","by":{"2":"29"}},{"t":"case","label":"Raines v. Byrd","cite":"521 U.S. 811","y":1997,"id":"1996/96-1671","sc":1,"op":1,"sum":"In a 7-to-2 decision, which avoided the question of the Act's constitutionality, the Court held that the individual congressmen lacked proper Article III standing to maintain their suit. The Court explained that the congressmen failed to show how the allegedly unconstitutional Act resulted in their personal injury, since it applied to the entire institution of Congress.","sumSrc":"Oyez","by":{"2":"19, 20, 40, 41","3":"21"}},{"t":"case","label":"Sinochem Int’l Co. v. Malay Int’l Shipping Corp.","cite":"549 U.S. 422","y":2007,"id":"2006/06-102","sc":1,"sum":"The Court ruled 9-0 that \"a court need not resolve whether it has [...] personal jurisdiction over the defendant if it determines that [...] a foreign tribunal is plainly the more suitable arbiter of the merits of the case.\" The opinion by Justice Ruth Bader Ginsburg held that while the first step of a court is normally to determine whether it has jurisdiction, a court can dismiss a case for forum non conveniens without establishing subject-matter or personal jurisdiction.","sumSrc":"Oyez","by":{"2":"59"}},{"t":"case","label":"Sprietsma v. Mercury Marine","cite":"537 U.S. 51","y":2002,"id":"2002/01-706","sc":1,"sum":"The Court held 8-0 that neither the text nor the intent of the FBSA preempts Sprietsma's common law claims, either explicitly or implicitly.","sumSrc":"Oyez","by":{"2":"51"}},{"t":"case","label":"Summers v. Earth Island Institute","cite":"555 U.S. 488","y":2009,"id":"2008/07-463","sc":1,"sum":"The Court held that the defendants did not have standing to challenge regulations of the U.S. Forest Service in the absence of a live dispute over the application of those regulations.","sumSrc":"Oyez","by":{"2":"19, 48, 56, 57, 58"}},{"t":"case","label":"Tenet v. Doe","cite":"544 U.S. 1","y":2005,"id":"2004/03-1395","sc":1,"sum":"The Court held that Totten barred the Does' suit. Totten, the Court ruled, prohibited judicial review in any case where success depended on the existence of a secret espionage relationship with the government. To risk revealing that relationship would endanger the essence of a spy's contract with the government - secrecy.","sumSrc":"Oyez","by":{"2":"59"}},{"t":"case","label":"Terry v. Allen","cite":"23 A. 150","y":1891,"court":"Conn.","url":"https://www.courtlistener.com/c/A./23/150/","ar":3,"by":{"2":"27","3":"9"}},{"t":"case","label":"Valley Forge Christian College v. Americans United for Separation of Church and State, Inc.","cite":"454 U.S. 464","y":1982,"id":"1981/80-327","sc":1,"op":1,"sum":"The Court held that Americans United for Separation of Church and State did not have standing to sue. Justice Rehnquist argued that the group did not pass the first prong of the Court's test for taxpayer standing.","sumSrc":"Oyez","by":{"2":"54"}},{"t":"case","label":"Wheeler v. Brown","cite":"26 Ill. 369","y":1861,"url":"https://www.courtlistener.com/c/Ill./26/369/","by":{"2":"49"}},{"t":"case","label":"Whitmore v. Arkansas","cite":"495 U.S. 149","y":1990,"id":"1989/88-7146","sc":1,"op":2,"sum":"Whitmore lacks standing to proceed in this Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"53"}},{"t":"case","label":"Whitney v. Smith","cite":"4 L.R. Ch. App. 513","y":1869,"url":"https://www.courtlistener.com/c/L.R.%20Ch.%20App./4/513/","by":{"2":"26"}},{"t":"case","label":"Wisener v. Burns","cite":"44 S.W.3d 289","y":2001,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W.3d/44/289/","by":{"2":"27"}},{"t":"usc","label":"29 U.S.C. § 1021","url":"https://www.law.cornell.edu/uscode/text/29/1021","subs":["(a)"],"by":{"2":"4, 36"}},{"t":"usc","label":"29 U.S.C. § 1022","url":"https://www.law.cornell.edu/uscode/text/29/1022","by":{"2":"4"}},{"t":"usc","label":"29 U.S.C. § 1054","url":"https://www.law.cornell.edu/uscode/text/29/1054","by":{"2":"4"}},{"t":"usc","label":"29 U.S.C. § 1108","url":"https://www.law.cornell.edu/uscode/text/29/1108","subs":["(a)"],"by":{"2":"6"}},{"t":"usc","label":"29 U.S.C. § 1131","url":"https://www.law.cornell.edu/uscode/text/29/1131","subs":["(b)"],"by":{"2":"55"}},{"t":"usc","label":"29 U.S.C. § 1133","url":"https://www.law.cornell.edu/uscode/text/29/1133","by":{"2":"4"}},{"t":"usc","label":"29 U.S.C. § 1144","url":"https://www.law.cornell.edu/uscode/text/29/1144","subs":["(b)(4)"],"stext":{"head":"§1144. Other laws","paras":[[0,"(a) Supersedure; effective date"],[0,"Except as provided in subsection (b) of this section, the provisions of this subchapter and subchapter III shall supersede any and all State laws insofar as they may now or hereafter relate to any employee benefit plan described in section 1003(a) of this title and not exempt under section 1003(b) of this title. This section shall take effect on January 1, 1975."],[0,"(b) Construction and application"],[0,"(1) This section shall not apply with respect to any cause of action which arose, or any act or omission which occurred, before January 1, 1975."],[0,"(2)(A) Except as provided in subparagraph (B), nothing in this subchapter shall be construed to exempt or relieve any person from any law of any State which regulates insurance, banking, or securities."],[0,"(B) Neither an employee benefit plan described in section 1003(a) of this title, which is not exempt under section 1003(b) of this title (other than a plan established primarily for the purpose of providing death benefits), nor any trust established under such a plan, shall be deemed to be an insurance company or other insurer, bank, trust company, or investment company or to be engaged in the business of insurance or banking for purposes of any law of any State purporting to regulate insurance companies, insurance contracts, banks, trust companies, or investment companies."],[0,"(3) Nothing in this section shall be construed to prohibit use by the Secretary of services or facilities of a State agency as permitted under section 1136 of this title."],[0,"(4) Subsection (a) shall not apply to any generally applicable criminal law of a State."],[0,"(5)(A) Except as provided in subparagraph (B), subsection (a) shall not apply to the Hawaii Prepaid Health Care Act (Haw. Rev. Stat. §§393–1 through 393–51)."],[0,"(B) Nothing in subparagraph (A) shall be construed to exempt from subsection (a)—"],[1,"(i) any State tax law relating to employee benefit plans, or"],[1,"(ii) any amendment of the Hawaii Prepaid Health Care Act enacted after September 2, 1974, to the extent it provides for more than the effective administration of such Act as in effect on such date."],[0,"(C) Notwithstanding subparagraph (A), parts 1 and 4 of this subtitle, and the preceding sections of this part to the extent they govern matters which are governed by the provisions of such parts 1 and 4, shall supersede the Hawaii Prepaid Health Care Act (as in effect on or after January 14, 1983), but the Secretary may enter into cooperative arrangements under this paragraph and section 1136 of this title with officials of the State of Hawaii to assist them in effectuating the policies of provisions of such Act which are superseded by such parts 1 and 4 and the preceding sections of this part."],[0,"(6)(A) Notwithstanding any other provision of this section—"],[1,"(i) in the case of an employee welfare benefit plan which is a multiple employer welfare arrangement and is fully insured (or which is a multiple employer welfare arrangement subject to an exemption under subparagraph (B)), any law of any State which regulates insurance may apply to such arrangement to the extent that such law provides—"],[2,"(I) standards, requiring the maintenance of specified levels of reserves and specified levels of contributions, which any such plan, or any trust established under such a plan, must meet in order to be considered under such law able to pay benefits in full when due, and"],[2,"(II) provisions to enforce such standards, and"],[1,"(ii) in the case of any other employee welfare benefit plan which is a multiple employer welfare arrangement, in addition to this subchapter, any law of any State which regulates insurance may apply to the extent not inconsistent with the preceding sections of this subchapter."],[0,"(B) The Secretary may, under regulations which may be prescribed by the Secretary, exempt from subparagraph (A)(ii), individually or by class, multiple employer welfare arrangements which are not fully insured. Any such exemption may be granted with respect to any arrangement or class of arrangements only if such arrangement or each arrangement which is a member of such class meets the requirements of section 1002(1) and section 1003 of this title necessary to be considered an employee welfare benefit plan to which this subchapter applies."],[0,"(C) Nothing in subparagraph (A) shall affect the manner or extent to which the provisions of this subchapter apply to an employee welfare benefit plan which is not a multiple employer welfare arrangement and which is a plan, fund, or program participating in, subscribing to, or otherwise using a multiple employer welfare arrangement to fund or administer benefits to such plan's participants and beneficiaries."],[0,"(D) For purposes of this paragraph, a multiple employer welfare arrangement shall be considered fully insured only if the terms of the arrangement provide for benefits the amount of all of which the Secretary determines are guaranteed under a contract, or policy of insurance, issued by an insurance company, insurance service, or insurance organization, qualified to conduct business in a State."],[0,"(7) Subsection (a) shall not apply to qualified domestic relations orders (within the meaning of section 1056(d)(3)(B)(i) of this title), qualified medical child support orders (within the meaning of section 1169(a)(2)(A) of this title), and the provisions of law referred to in section 1169(a)(2)(B)(ii) of this title to the extent they apply to qualified medical child support orders."],[0,"(8) Subsection (a) of this section shall not be construed to preclude any State cause of action—"],[1,"(A) with respect to which the State exercises its acquired rights under section 1169(b)(3) of this title with respect to a group health plan (as defined in section 1167(1) of this title), or"],[1,"(B) for recoupment of payment with respect to items or services pursuant to a State plan for medical assistance approved under title XIX of the Social Security Act [42 U.S.C. 1396 et seq.] which would not have been payable if such acquired rights had been executed before payment with respect to such items or services by the group health plan."],[0,"(9) For additional provisions relating to group health plans, see section 1191 of this title."],[0,"(c) Definitions"],[0,"For purposes of this section:"],[1,"(1) The term \"State law\" includes all laws, decisions, rules, regulations, or other State action having the effect of law, of any State. A law of the United States applicable only to the District of Columbia shall be treated as a State law rather than a law of the United States."],[1,"(2) The term \"State\" includes a State, any political subdivisions thereof, or any agency or instrumentality of either, which purports to regulate, directly or indirectly, the terms and conditions of employee benefit plans covered by this subchapter."],[0,"(d) Alteration, amendment, modification, invalidation, impairment, or supersedure of any law of the United States prohibited"],[0,"Nothing in this subchapter shall be construed to alter, amend, modify, invalidate, impair, or supersede any law of the United States (except as provided in sections 1031 and 1137(b) of this title) or any rule or regulation issued under any such law."],[0,"(e) Automatic contribution arrangements"],[0,"(1) Notwithstanding any other provision of this section, this subchapter shall supersede any law of a State which would directly or indirectly prohibit or restrict the inclusion in any plan of an automatic contribution arrangement. The Secretary may prescribe regulations which would establish minimum standards that such an arrangement would be required to satisfy in order for this subsection to apply in the case of such arrangement."],[0,"(2) For purposes of this subsection, the term \"automatic contribution arrangement\" means an arrangement—"],[1,"(A) under which a participant may elect to have the plan sponsor make payments as contributions under the plan on behalf of the participant, or to the participant directly in cash,"],[1,"(B) under which a participant is treated as having elected to have the plan sponsor make such contributions in an amount equal to a uniform percentage of compensation provided under the plan until the participant specifically elects not to have such contributions made (or specifically elects to have such contributions made at a different percentage), and"],[1,"(C) under which such contributions are invested in accordance with regulations prescribed by the Secretary under section 1104(c)(5) of this title."],[0,"(3)(A) The plan administrator of an automatic contribution arrangement shall, within a reasonable period before such plan year, provide to each participant to whom the arrangement applies for such plan year notice of the participant's rights and obligations under the arrangement which—"],[1,"(i) is sufficiently accurate and comprehensive to apprise the participant of such rights and obligations, and"],[1,"(ii) is written in a manner calculated to be understood by the average participant to whom the arrangement applies."],[0,"(B) A notice shall not be treated as meeting the requirements of subparagraph (A) with respect to a participant unless—"],[1,"(i) the notice includes an explanation of the participant's right under the arrangement not to have elective contributions made on the participant's behalf (or to elect to have such contributions made at a different percentage),"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1144?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1144. Other laws","tname":"Labor","by":{"2":"55"}},{"t":"usc","label":"29 U.S.C. § 1306","url":"https://www.law.cornell.edu/uscode/text/29/1306","subs":["(a)"],"by":{"2":"5"}},{"t":"usc","label":"29 U.S.C. § 1322","url":"https://www.law.cornell.edu/uscode/text/29/1322","subs":["(a)"],"stext":{"head":"§1322. Single-employer plan benefits guaranteed","paras":[[0,"(a) Nonforfeitable benefits"],[0,"Subject to the limitations contained in subsection (b), the corporation shall guarantee, in accordance with this section, the payment of all nonforfeitable benefits (other than benefits becoming nonforfeitable solely on account of the termination of a plan) under a single-employer plan which terminates at a time when this subchapter applies to it."],[0,"(b) Exceptions"],[0,"(1) Except to the extent provided in paragraph (7)—"],[1,"(A) no benefits provided by a plan which has been in effect for less than 60 months at the time the plan terminates shall be guaranteed under this section, and"],[1,"(B) any increase in the amount of benefits under a plan resulting from a plan amendment which was made, or became effective, whichever is later, within 60 months before the date on which the plan terminates shall be disregarded."],[0,"(2) For purposes of this subsection, the time a successor plan (within the meaning of section 1321(a) of this title) has been in effect includes the time a previously established plan (within the meaning of section 1321(a) of this title) was in effect. For purposes of determining what benefits are guaranteed under this section in the case of a plan to which section 1321 of this title does not apply on September 3, 1974, the 60-month period referred to in paragraph (1) shall be computed beginning on the first date on which such section does apply to the plan."],[0,"(3) The amount of monthly benefits described in subsection (a) provided by a plan, which are guaranteed under this section with respect to a participant, shall not have an actuarial value which exceeds the actuarial value of a monthly benefit in the form of a life annuity commencing at age 65 equal to the lesser of—"],[1,"(A) his average monthly gross income from his employer during the 5 consecutive calendar year period (or, if less, during the number of calendar years in such period in which he actively participates in the plan) during which his gross income from that employer was greater than during any other such period with that employer determined by dividing 1/12 of the sum of all such gross income by the number of such calendar years in which he had such gross income, or"],[1,"(B) $750 multiplied by a fraction, the numerator of which is the contribution and benefit base (determined under section 230 of the Social Security Act [42 U.S.C. 430]) in effect at the time the plan terminates and the denominator of which is such contribution and benefit base in effect in calendar year 1974."],[0,"The provisions of this paragraph do not apply to non-basic benefits. The maximum guaranteed monthly benefit shall not be reduced solely on account of the age of a participant in the case of a benefit payable by reason of disability that occurred on or before the termination date, if the participant demonstrates to the satisfaction of the corporation that the Social Security Administration has determined that the participant satisfies the definition of disability under title II or XVI of the Social Security Act [42 U.S.C. 401 et seq.; 1381 et seq.], and the regulations thereunder. If a benefit payable by reason of disability is converted to an early or normal retirement benefit for reasons other than a change in the health of the participant, such early or normal retirement benefit shall be treated as a continuation of the benefit payable by reason of disability and this subparagraph 1 shall continue to apply."],[0,"(4)(A) The actuarial value of a benefit, for purposes of this subsection, shall be determined in accordance with regulations prescribed by the corporation."],[0,"(B) For purposes of paragraph (3)—"],[1,"(i) the term \"gross income\" means \"earned income\" within the meaning of section 911(b) of title 26 (determined without regard to any community property laws),"],[1,"(ii) in the case of a participant in a plan under which contributions are made by more than one employer, amounts received as gross income from any employer under that plan shall be aggregated with amounts received from any other employer under that plan during the same period, and"],[1,"(iii) any non-basic benefit shall be disregarded."],[0,"(5)(A) For purposes of this paragraph, the term \"majority owner\" means an individual who, at any time during the 60-month period ending on the date the determination is being made—"],[1,"(i) owns the entire interest in an unincorporated trade or business,"],[1,"(ii) in the case of a partnership, is a partner who owns, directly or indirectly, 50 percent or more of either the capital interest or the profits interest in such partnership, or"],[1,"(iii) in the case of a corporation, owns, directly or indirectly, 50 percent or more in value of either the voting stock of that corporation or all the stock of that corporation."],[0,"For purposes of clause (iii), the constructive ownership rules of section 1563(e) of title 26 (other than paragraph (3)(C) thereof) shall apply, including the application of such rules under section 414(c) of title 26."],[0,"(B) In the case of a participant who is a majority owner, the amount of benefits guaranteed under this section shall equal the product of—"],[1,"(i) a fraction (not to exceed 1) the numerator of which is the number of years from the later of the effective date or the adoption date of the plan to the termination date, and the denominator of which is 10, and"],[1,"(ii) the amount of benefits that would be guaranteed under this section if the participant were not a majority owner."],[0,"(6)(A) No benefits accrued under a plan after the date on which the Secretary of the Treasury issues notice that he has determined that any trust which is a part of a plan does not meet the requirements of section 401(a) of title 26, or that the plan does not meet the requirements of section 404(a)(2) of title 26, are guaranteed under this section unless such determination is erroneous. This subparagraph does not apply if the Secretary subsequently issues a notice that such trust meets the requirements of section 401(a) of title 26 or that the plan meets the requirements of section 404(a)(2) of title 26 and if the Secretary determines that the trust or plan has taken action necessary to meet such requirements during the period between the issuance of the notice referred to in the preceding sentence and the issuance of the notice referred to in this sentence."],[0,"(B) No benefits accrued under a plan after the date on which an amendment of the plan is adopted which causes the Secretary of the Treasury to determine that any trust under the plan has ceased to meet the requirements of section 401(a) of title 26 or that the plan has ceased to meet the requirements of section 404(a)(2) of title 26, are guaranteed under this section unless such determination is erroneous. This subparagraph shall not apply if the amendment is revoked as of the date it was first effective or amended to comply with such requirements."],[0,"(7) Benefits described in paragraph (1) are guaranteed only to the extent of the greater of—"],[1,"(A) 20 percent of the amount which, but for the fact that the plan or amendment has not been in effect for 60 months or more, would be guaranteed under this section, or"],[1,"(B) $20 per month,"],[0,"multiplied by the number of years (but not more than 5) the plan or amendment, as the case may be, has been in effect. In determining how many years a plan or amendment has been in effect for purposes of this paragraph, the first 12 months beginning with the date on which the plan or amendment is made or first becomes effective (whichever is later) constitutes one year, and each consecutive period of 12 months thereafter constitutes an additional year. This paragraph does not apply to benefits payable under a plan unless the corporation finds substantial evidence that the plan was terminated for a reasonable business purpose and not for the purpose of obtaining the payment of benefits by the corporation under this subchapter."],[0,"(8) If an unpredictable contingent event benefit (as defined in section 1056(g)(1) of this title) is payable by reason of the occurrence of any event, this section shall be applied as if a plan amendment had been adopted on the date such event occurred."],[0,"(c) Payment by corporation to participants and beneficiaries of recovery percentage of outstanding amount of benefit liabilities"],[0,"(1) In addition to benefits paid under the preceding provisions of this section with respect to a terminated plan, the corporation shall pay the portion of the amount determined under paragraph (2) which is allocated with respect to each participant under section 1344(a) of this title. Such payment shall be made to such participant or to such participant's beneficiaries (including alternate payees, within the meaning of section 1056(d)(3)(K) of this title)."],[0,"(2) The amount determined under this paragraph is an amount equal to the product derived by multiplying—"],[1,"(A) the outstanding amount of benefit liabilities under the plan (including interest calculated from the termination date), by"],[1,"(B) the applicable recovery ratio."],[0,"(3)(A) In general.—Except as provided in subparagraph (C), the term \"recovery ratio\" means the ratio which—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1322?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1322. Single-employer plan benefits guaranteed","tname":"Labor","by":{"2":"5"}},{"t":"usc","label":"29 U.S.C. § 1362","url":"https://www.law.cornell.edu/uscode/text/29/1362","subs":["(b)"],"stext":{"head":"§1362. Liability for termination of single-employer plans under a distress termination or a termination by corporation","paras":[[0,"(a) In general"],[0,"In any case in which a single-employer plan is terminated in a distress termination under section 1341(c) of this title or a termination otherwise instituted by the corporation under section 1342 of this title, any person who is, on the termination date, a contributing sponsor of the plan or a member of such a contributing sponsor's controlled group shall incur liability under this section. The liability under this section of all such persons shall be joint and several. The liability under this section consists of—"],[1,"(1) liability to the corporation, to the extent provided in subsection (b), and"],[1,"(2) liability to the trustee appointed under subsection (b) or (c) of section 1342 of this title, to the extent provided in subsection (c)."],[0,"(b) Liability to corporation"],[0,"(1) Amount of liability"],[0,"(A) In general"],[2,"Except as provided in subparagraph (B), the liability to the corporation of a person described in subsection (a) shall be the total amount of the unfunded benefit liabilities (as of the termination date) to all participants and beneficiaries under the plan, together with interest (at a reasonable rate) calculated from the termination date in accordance with regulations prescribed by the corporation."],[0,"(B) Special rule in case of subsequent insufficiency"],[2,"For purposes of subparagraph (A), in any case described in section 1341(c)(3)(C)(ii) of this title, actuarial present values shall be determined as of the date of the notice to the corporation (or the finding by the corporation) described in such section."],[0,"(2) Payment of liability"],[0,"(A) In general"],[2,"Except as provided in subparagraph (B), the liability to the corporation under this subsection shall be due and payable to the corporation as of the termination date, in cash or securities acceptable to the corporation."],[0,"(B) Special rule"],[2,"Payment of so much of the liability under paragraph (1)(A) as exceeds 30 percent of the collective net worth of all persons described in subsection (a) (including interest) shall be made under commercially reasonable terms prescribed by the corporation. The parties involved shall make a reasonable effort to reach agreement on such commercially reasonable terms. Any such terms prescribed by the corporation shall provide for deferral of 50 percent of any amount of liability otherwise payable for any year under this subparagraph if a person subject to such liability demonstrates to the satisfaction of the corporation that no person subject to such liability has any individual pre-tax profits for such person's fiscal year ending during such year."],[0,"(3) Alternative arrangements"],[1,"The corporation and any person liable under this section may agree to alternative arrangements for the satisfaction of liability to the corporation under this subsection."],[0,"(c) Liability to section 1342 trustee"],[0,"A person described in subsection (a) shall be subject to liability under this subsection to the trustee appointed under subsection (b) or (c) of section 1342 of this title. The liability of such person under this subsection shall consist of—"],[1,"(1) the sum of the shortfall amortization charge (within the meaning of section 1083(c)(1) of this title and 430(d)(1) 1 of title 26) with respect to the plan (if any) for the plan year in which the termination date occurs, plus the aggregate total of shortfall amortization installments (if any) determined for succeeding plan years under section 1083(c)(2) of this title and section 430(d)(2) of title 26 (which, for purposes of this subparagraph, shall include any increase in such sum which would result if all applications for waivers of the minimum funding standard under section 1082(c) of this title and section 412(c) of title 26 which are pending with respect to such plan were denied and if no additional contributions (other than those already made by the termination date) were made for the plan year in which the termination date occurs or for any previous plan year), and"],[1,"(2) the sum of the waiver amortization charge (within the meaning of section 1083(e)(1) of this title and 430(e)(1) 1 of title 26) with respect to the plan (if any) for the plan year in which the termination date occurs, plus the aggregate total of waiver amortization installments (if any) determined for succeeding plan years under section 1083(e)(2) of this title and section 430(e)(2) of title 26,"],[0,"together with interest (at a reasonable rate) calculated from the termination date in accordance with regulations prescribed by the corporation. The liability under this subsection shall be due and payable to such trustee as of the termination date, in cash or securities acceptable to such trustee."],[0,"(d) Definitions"],[0,"(1) Collective net worth of persons subject to liability"],[0,"(A) In general"],[2,"The collective net worth of persons subject to liability in connection with a plan termination consists of the sum of the individual net worths of all persons who—"],[3,"(i) have individual net worths which are greater than zero, and"],[3,"(ii) are (as of the termination date) contributing sponsors of the terminated plan or members of their controlled groups."],[0,"(B) Determination of net worth"],[2,"For purposes of this paragraph, the net worth of a person is—"],[3,"(i) determined on whatever basis best reflects, in the determination of the corporation, the current status of the person's operations and prospects at the time chosen for determining the net worth of the person, and"],[3,"(ii) increased by the amount of any transfers of assets made by the person which are determined by the corporation to be improper under the circumstances, including any such transfers which would be inappropriate under title 11 if the person were a debtor in a case under chapter 7 of such title."],[0,"(C) Timing of determination"],[2,"For purposes of this paragraph, determinations of net worth shall be made as of a day chosen by the corporation (during the 120-day period ending with the termination date) and shall be computed without regard to any liability under this section."],[0,"(2) Pre-tax profits"],[1,"The term \"pre-tax profits\" means—"],[2,"(A) except as provided in subparagraph (B), for any fiscal year of any person, such person's consolidated net income (excluding any extraordinary charges to income and including any extraordinary credits to income) for such fiscal year, as shown on audited financial statements prepared in accordance with generally accepted accounting principles, or"],[2,"(B) for any fiscal year of an organization described in section 501(c) of title 26, the excess of income over expenses (as such terms are defined for such organizations under generally accepted accounting principles),"],[1,"before provision for or deduction of Federal or other income tax, any contribution to any single-employer plan of which such person is a contributing sponsor at any time during the period beginning on the termination date and ending with the end of such fiscal year, and any amounts required to be paid for such fiscal year under this section. The corporation may by regulation require such information to be filed on such forms as may be necessary to determine the existence and amount of such pre-tax profits."],[0,"(e) Treatment of substantial cessation of operations"],[0,"(1) General rule"],[1,"Except as provided in paragraphs (3) and (4), if there is a substantial cessation of operations at a facility in any location, the employer shall be treated with respect to any single employer plan established and maintained by the employer covering participants at such facility as if the employer were a substantial employer under a plan under which more than one employer makes contributions and the provisions of sections 1363, 1364, and 1365 of this title shall apply."],[0,"(2) Substantial cessation of operations"],[1,"For purposes of this subsection:"],[0,"(A) In general"],[2,"The term \"substantial cessation of operations\" means a permanent cessation of operations at a facility which results in a workforce reduction of a number of eligible employees at the facility equivalent to more than 15 percent of the number of all eligible employees of the employer, determined immediately before the earlier of—"],[3,"(i) the date of the employer's decision to implement such cessation, or"],[3,"(ii) in the case of a workforce reduction which includes 1 or more eligible employees described in paragraph (6)(B), the earliest date on which any such eligible employee was separated from employment."],[0,"(B) Workforce reduction"],[2,"Subject to subparagraphs (C) and (D), the term \"workforce reduction\" means the number of eligible employees at a facility who are separated from employment by reason of the permanent cessation of operations of the employer at the facility."],[0,"(C) Relocation of workforce"],[2,"An eligible employee separated from employment at a facility shall not be taken into account in computing a workforce reduction if, within a reasonable period of time, the employee is replaced by the employer, at the same or another facility located in the United States, by an employee who is a citizen or resident of the United States."],[0,"(D) Dispositions"],[2,"If, whether by reason of a sale or other disposition of the assets or stock of a contributing sponsor (or any member of the same controlled group as such a sponsor) of the plan relating to operations at a facility or otherwise, an employer (the \"transferee employer\") other than the employer which experiences the substantial cessation of operations (the \"transferor employer\") conducts any portion of such operations, then—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1362?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1362. Liability for termination of single-employer plans under a distress termination or a termination by corporation","tname":"Labor","by":{"2":"4, 54"}},{"t":"reg","label":"OTHER AUTHORITIES, 42 Fed. Reg. 18,734","url":"https://www.govinfo.gov/link/fr/42/18734","by":{"2":"10"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(b)(1)"],"by":{"2":"12, 51"}},{"t":"case","label":"Gaither v. Aetna Life Ins. Co.","cite":"394 F.3d 792","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/394/792/","by":{"3":"12"}},{"t":"reg","label":"26 C.F.R. § 1.401-1","url":"https://www.ecfr.gov/current/title-26/section-1.401-1","subs":["(3)(iv)"],"by":{"3":"7"}}]};